css:
@property --ape-blocks-cx {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 12%;
}
@property --ape-blocks-cy {
  syntax: "<percentage>";
  inherits: false;
  initial-value: -20%;
}
@property --ape-blocks-pct {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.ape-blocks {
  /* theme: override these four to re-skin */
  --ape-blocks-bg: oklch(0.975 0.008 82);
  --ape-blocks-paper: oklch(0.993 0.004 85);
  --ape-blocks-ink: oklch(0.25 0.02 58);
  --ape-blocks-accent: oklch(0.6 0.16 42);

  --ape-blocks-line: color-mix(in oklch, var(--ape-blocks-ink) 9%, transparent);
  --ape-blocks-line2: color-mix(in oklch, var(--ape-blocks-ink) 17%, transparent);
  --ape-blocks-mute: color-mix(in oklch, var(--ape-blocks-ink) 60%, var(--ape-blocks-paper));
  --ape-blocks-faint: color-mix(in oklch, var(--ape-blocks-ink) 36%, var(--ape-blocks-paper));
  --ape-blocks-hover: color-mix(in oklch, var(--ape-blocks-ink) 6%, transparent);
  --ape-blocks-press: color-mix(in oklch, var(--ape-blocks-ink) 10%, transparent);
  --ape-blocks-tint: color-mix(in oklch, var(--ape-blocks-accent) 11%, var(--ape-blocks-paper));
  --ape-blocks-tint2: color-mix(in oklch, var(--ape-blocks-accent) 22%, var(--ape-blocks-paper));
  --ape-blocks-deep: color-mix(in oklch, var(--ape-blocks-accent) 78%, var(--ape-blocks-ink));
  --ape-blocks-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-blocks-out: cubic-bezier(.32, .72, 0, 1);
  --ape-blocks-spring: linear(0, 0.1 4%, 0.36 9.5%, 0.7 16%, 0.94 23%, 1.04 29%, 1.06 34%, 1.03 41%, 1.005 52%, 0.998 64%, 1);

  position: relative; width: 100%; height: var(--ape-blocks-h, 680px);
  container-type: inline-size; container-name: ape-blocks;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-blocks-bg); color: var(--ape-blocks-ink); color-scheme: light;
  accent-color: var(--ape-blocks-accent);
  font: 14px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px var(--ape-blocks-line2);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--ape-blocks-accent); outline-offset: 2px; border-radius: 4px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h1, & p, & dl, & dd, & ol, & ul { margin: 0; }
  & ul, & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 600 10.5px/1 ui-monospace, Menlo, monospace; padding: 2px 5px 3px; border-radius: 4px;
    color: var(--ape-blocks-mute); background: var(--ape-blocks-paper);
    box-shadow: inset 0 0 0 1px var(--ape-blocks-line2), inset 0 -1px 0 var(--ape-blocks-line2);
  }
}

/* ── shell grid ─────────────────────────────────────── */
.ape-blocks .ape-blocks-app {
  height: 100%;
  display: grid;
  grid-template-columns: 248px minmax(0, 1fr) 212px;
  grid-template-rows: 48px minmax(0, 1fr);
  grid-template-areas: "side top rail" "side doc rail";
  timeline-scope: --ape-blocks-doc;
}

/* ── sidebar ────────────────────────────────────────── */
.ape-blocks .ape-blocks-side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 6px;
  padding: 12px 10px; overflow-y: auto; scrollbar-width: thin;
  border-right: 1px solid var(--ape-blocks-line);
}
.ape-blocks .ape-blocks-ws {
  display: flex; align-items: center; gap: 10px; padding: 4px 6px 10px;
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--ape-blocks-mute); }
}
.ape-blocks .ape-blocks-logo {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; flex: none;
  background: linear-gradient(160deg, var(--ape-blocks-accent), var(--ape-blocks-deep));
  color: var(--ape-blocks-paper); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-blocks-ink) 15%, transparent);
  & svg { width: 18px; height: 18px; stroke-width: 1.7; }
}
.ape-blocks .ape-blocks-find {
  display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 6px 0 9px; margin-bottom: 6px;
  border-radius: 8px; color: var(--ape-blocks-mute); background: var(--ape-blocks-hover);
  transition: background .18s var(--ape-blocks-ease), box-shadow .18s var(--ape-blocks-ease);
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; color: var(--ape-blocks-ink); font-size: 13px; }
  & input::placeholder { color: var(--ape-blocks-mute); }
  & input::-webkit-search-cancel-button { display: none; }
  &:has(input:focus) { background: var(--ape-blocks-paper); box-shadow: 0 0 0 1px var(--ape-blocks-line2), 0 0 0 4px var(--ape-blocks-tint); }
  &:has(input:not(:placeholder-shown)) kbd { display: none; }
}
.ape-blocks .ape-blocks-sec {
  font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase;
  color: var(--ape-blocks-faint); padding: 8px 8px 4px;
}
.ape-blocks .ape-blocks-tree { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1px; }
.ape-blocks .ape-blocks-tree [role="group"] { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1px; }
.ape-blocks .ape-blocks-tree li { min-width: 0; }
.ape-blocks .ape-blocks-row {
  --d: 0;
  display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 8px 0 calc(4px + var(--d) * 16px);
  border-radius: 7px; color: color-mix(in oklch, var(--ape-blocks-ink) 82%, var(--ape-blocks-paper));
  cursor: pointer; user-select: none; outline-offset: -2px;
  transition: background .15s var(--ape-blocks-ease), color .15s;
  &:hover { background: var(--ape-blocks-hover); }
  & .ape-blocks-twist {
    display: grid; place-items: center; width: 18px; height: 18px; border-radius: 4px; color: var(--ape-blocks-faint);
    & svg { width: 12px; height: 12px; stroke-width: 2; transition: transform .22s var(--ape-blocks-out); }
    &:hover { background: var(--ape-blocks-press); color: var(--ape-blocks-ink); }
    &.is-leaf { visibility: hidden; }
  }
  & .ape-blocks-ricon { color: var(--ape-blocks-mute); display: grid; }
  & .ape-blocks-rname { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-size: 13.5px; }
  & mark { background: var(--ape-blocks-tint2); color: inherit; border-radius: 2px; }
  & .ape-blocks-rcount { font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--ape-blocks-faint); font-variant-numeric: tabular-nums; }
}
.ape-blocks [role="treeitem"][aria-expanded="true"] > .ape-blocks-row .ape-blocks-twist svg { transform: rotate(90deg); }
.ape-blocks [role="treeitem"][aria-expanded="false"] > [role="group"] { display: none; }
.ape-blocks [role="treeitem"][aria-selected="true"] > .ape-blocks-row {
  background: var(--ape-blocks-tint); color: var(--ape-blocks-ink); font-weight: 600;
  & .ape-blocks-ricon { color: var(--ape-blocks-accent); }
}
.ape-blocks .ape-blocks-nohit { padding: 6px 10px; font-size: 12.5px; color: var(--ape-blocks-mute); }
.ape-blocks .ape-blocks-newpage {
  display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 8px; margin-top: auto;
  border-radius: 7px; color: var(--ape-blocks-mute); font-size: 13px;
  & kbd { margin-left: auto; }
  &:hover { background: var(--ape-blocks-hover); color: var(--ape-blocks-ink); }
}

/* ── top bar ────────────────────────────────────────── */
.ape-blocks .ape-blocks-top {
  grid-area: top; position: relative; z-index: 2; display: flex; align-items: center; gap: 8px; padding: 0 12px 0 16px;
  background: var(--ape-blocks-paper); min-width: 0;
}
.ape-blocks .ape-blocks-pagesbtn { display: none; }
.ape-blocks .ape-blocks-crumbs {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 2px; font-size: 13px; color: var(--ape-blocks-mute); overflow: hidden;
  & > span { padding: 3px 6px; white-space: nowrap; }
  & button { padding: 3px 6px; border-radius: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 22ch; }
  & button:hover { background: var(--ape-blocks-hover); color: var(--ape-blocks-ink); }
  & button[aria-current] { color: var(--ape-blocks-ink); font-weight: 560; max-width: 40ch; }
  & i { font-style: normal; color: var(--ape-blocks-faint); }
}
.ape-blocks .ape-blocks-saved {
  font-size: 12px; color: var(--ape-blocks-faint); white-space: nowrap; display: inline-flex; align-items: center; gap: 6px;
  &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: color-mix(in oklch, oklch(0.62 0.13 150) 80%, var(--ape-blocks-paper)); transition: background .2s; }
  &.is-saving::before { background: var(--ape-blocks-accent); animation: ape-blocks-pulse .8s ease-in-out infinite alternate; }
}
.ape-blocks .ape-blocks-tools { display: flex; gap: 2px; }
.ape-blocks .ape-blocks-ibtn {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 7px; color: var(--ape-blocks-mute);
  transition: background .15s var(--ape-blocks-ease), color .15s, transform .15s var(--ape-blocks-ease);
  &:hover { background: var(--ape-blocks-hover); color: var(--ape-blocks-ink); }
  &:active { transform: scale(.94); }
  &:disabled { opacity: .35; pointer-events: none; }
  &[aria-pressed="true"] { background: var(--ape-blocks-tint); color: var(--ape-blocks-deep); }
}
.ape-blocks .ape-blocks-prog {
  position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; transform-origin: 0 50%;
  background: var(--ape-blocks-accent); transform: scaleX(var(--ape-blocks-read, 0));
}
.ape-blocks .ape-blocks-top::after {
  content: ""; position: absolute; inset: auto 0 -1px 0; height: 1px; background: var(--ape-blocks-line);
  opacity: var(--ape-blocks-edge, 0); transition: opacity .2s;
}
@supports (animation-timeline: scroll()) {
  .ape-blocks .ape-blocks-doc { scroll-timeline: --ape-blocks-doc block; }
  .ape-blocks .ape-blocks-prog { animation: ape-blocks-grow linear both; animation-timeline: --ape-blocks-doc; }
  .ape-blocks .ape-blocks-top::after { transition: none; animation: ape-blocks-edge linear both; animation-timeline: --ape-blocks-doc; animation-range: 0 40px; }
}
@keyframes ape-blocks-grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes ape-blocks-edge { from { opacity: 0; } to { opacity: 1; } }
@keyframes ape-blocks-pulse { from { opacity: .35; } to { opacity: 1; } }

/* ── document ───────────────────────────────────────── */
.ape-blocks .ape-blocks-doc {
  grid-area: doc; min-height: 0; overflow-y: auto; overflow-x: hidden; background: var(--ape-blocks-paper);
  scrollbar-width: thin; scrollbar-color: var(--ape-blocks-line2) transparent; outline: none;
  overscroll-behavior: contain;
}
.ape-blocks .ape-blocks-page {
  --ape-blocks-measure: 680px;
  max-width: var(--ape-blocks-measure); margin: 0 auto; padding: 0 clamp(18px, 5cqi, 56px) 120px;
  transition: max-width .45s var(--ape-blocks-out);
}
.ape-blocks.is-wide .ape-blocks-page { --ape-blocks-measure: 1200px; }
.ape-blocks .ape-blocks-cover {
  position: relative; height: clamp(84px, 13cqi, 132px); margin: 0 calc(-1 * clamp(18px, 5cqi, 56px));
  overflow: hidden; border-radius: 0 0 2px 2px;
  transition: --ape-blocks-cx .9s var(--ape-blocks-out), --ape-blocks-cy .9s var(--ape-blocks-out);
  background:
    radial-gradient(120% 140% at var(--ape-blocks-cx) 120%, color-mix(in oklch, var(--ape-blocks-accent) 85%, oklch(0.8 0.15 70)) 0 22%, transparent 52%),
    radial-gradient(90% 120% at calc(100% - var(--ape-blocks-cx)) var(--ape-blocks-cy), color-mix(in oklch, var(--ape-blocks-deep) 70%, var(--ape-blocks-ink)) 0 30%, transparent 62%),
    linear-gradient(100deg, color-mix(in oklch, var(--ape-blocks-accent) 55%, var(--ape-blocks-paper)), color-mix(in oklch, var(--ape-blocks-accent) 25%, oklch(0.9 0.05 80)));
  & i {
    position: absolute; inset: 0; border-radius: 50%;
    background: radial-gradient(closest-side, color-mix(in oklch, oklch(0.92 0.1 85) 70%, transparent), transparent);
    width: 46%; height: 220%; top: -60%; left: 30%; opacity: .45; mix-blend-mode: soft-light;
  }
  & i:nth-child(2) { left: 62%; width: 30%; top: -30%; opacity: .35; }
  & i:nth-child(3) {
    inset: 0; width: auto; height: auto; border-radius: 0; opacity: .5; mix-blend-mode: multiply;
    background: repeating-linear-gradient(90deg, transparent 0 22px, color-mix(in oklch, var(--ape-blocks-ink) 7%, transparent) 22px 23px);
    mask: linear-gradient(transparent, #000);
  }
}
.ape-blocks .ape-blocks-head { position: relative; padding: 0 0 6px; }
.ape-blocks .ape-blocks-picon {
  display: grid; place-items: center; width: 64px; height: 64px; margin: -34px 0 10px; border-radius: 16px;
  background: var(--ape-blocks-paper); color: var(--ape-blocks-accent);
  box-shadow: 0 0 0 1px var(--ape-blocks-line2), 0 10px 24px -14px color-mix(in oklch, var(--ape-blocks-ink) 50%, transparent);
  & svg { width: 34px; height: 34px; stroke-width: 1.4; }
}
.ape-blocks .ape-blocks-title {
  font-size: clamp(26px, 3.3cqi, 38px); line-height: 1.12; font-weight: 760; letter-spacing: -.025em;
  text-wrap: balance; outline: none; padding: 2px 0 8px; min-height: 1.2em;
  &:empty::before { content: attr(data-ph); color: var(--ape-blocks-faint); }
}
.ape-blocks .ape-blocks-props {
  display: grid; grid-template-columns: max-content 1fr; column-gap: 18px; row-gap: 3px; padding: 6px 0 14px;
  border-bottom: 1px solid var(--ape-blocks-line); margin-bottom: 14px; font-size: 13px;
  & dt { color: var(--ape-blocks-mute); display: flex; align-items: center; gap: 7px; }
  & dt svg { width: 14px; height: 14px; }
  & dd { color: var(--ape-blocks-ink); }
  & .ape-blocks-pill { display: inline-block; padding: 0 8px; border-radius: 99px; font-size: 12px; font-weight: 560; background: var(--ape-blocks-tint2); color: var(--ape-blocks-deep); }
}

/* ── blocks ─────────────────────────────────────────── */
.ape-blocks .ape-blocks-list { display: flex; flex-direction: column; }
.ape-blocks .ape-blocks-b {
  --i: 0;
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: start; column-gap: 6px;
  margin: 0 0 0 -52px; padding: 2px 0 2px 52px; border-radius: 6px;
  transition: opacity .28s var(--ape-blocks-ease), transform .32s var(--ape-blocks-out), background .2s;
  @starting-style { opacity: 0; transform: translateY(-5px); }
  &.is-sel { background: var(--ape-blocks-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-blocks-accent) 30%, transparent); }
  &.is-dragging { opacity: .32; }
  &:not(:has(.ape-blocks-mark)) { grid-template-columns: minmax(0, 1fr); }
}
.ape-blocks .ape-blocks-list.is-enter .ape-blocks-b { transition-delay: calc(min(var(--i), 14) * 22ms); }
.ape-blocks .ape-blocks-gut {
  position: absolute; left: 4px; top: 3px; display: flex; gap: 0; opacity: 0;
  transition: opacity .16s var(--ape-blocks-ease);
  & button { display: grid; place-items: center; width: 22px; height: 24px; border-radius: 5px; color: var(--ape-blocks-faint); touch-action: none; }
  & button:hover { background: var(--ape-blocks-hover); color: var(--ape-blocks-ink); }
  & .ape-blocks-grip { cursor: grab; }
  & .ape-blocks-grip svg { stroke: none; fill: currentColor; }
}
.ape-blocks .ape-blocks-b:hover > .ape-blocks-gut,
.ape-blocks .ape-blocks-b:focus-within > .ape-blocks-gut,
.ape-blocks .ape-blocks-b.is-sel > .ape-blocks-gut { opacity: 1; }
.ape-blocks .ape-blocks-b[data-type="h1"] > .ape-blocks-gut { top: 14px; }
.ape-blocks .ape-blocks-b[data-type="h2"] > .ape-blocks-gut { top: 12px; }
.ape-blocks .ape-blocks-b[data-type="h3"] > .ape-blocks-gut { top: 8px; }

.ape-blocks .ape-blocks-t {
  outline: none; min-height: 1.55em; padding: 3px 2px; white-space: pre-wrap; overflow-wrap: anywhere;
  text-wrap: pretty; caret-color: var(--ape-blocks-accent);
  & b, & strong { font-weight: 680; }
  & code {
    font: 500 .88em/1 ui-monospace, Menlo, monospace; padding: .16em .38em; border-radius: 4px;
    background: color-mix(in oklch, var(--ape-blocks-accent) 9%, var(--ape-blocks-bg)); color: var(--ape-blocks-deep);
  }
  & u { text-decoration-color: var(--ape-blocks-accent); text-underline-offset: 3px; }
}
.ape-blocks .ape-blocks-t:empty::before { content: attr(data-ph); color: transparent; pointer-events: none; transition: color .15s; }
.ape-blocks .ape-blocks-t:empty:focus::before,
.ape-blocks .ape-blocks-b:not([data-type="p"]) > .ape-blocks-t:empty::before,
.ape-blocks .ape-blocks-list:has(> .ape-blocks-b:only-child) .ape-blocks-t:empty::before { color: var(--ape-blocks-faint); }

.ape-blocks .ape-blocks-b[data-type="h1"] { margin-top: 22px; }
.ape-blocks .ape-blocks-b[data-type="h2"] { margin-top: 16px; }
.ape-blocks .ape-blocks-b[data-type="h3"] { margin-top: 10px; }
.ape-blocks [data-type="h1"] > .ape-blocks-t { font-size: 1.75em; font-weight: 740; line-height: 1.22; letter-spacing: -.02em; text-wrap: balance; }
.ape-blocks [data-type="h2"] > .ape-blocks-t { font-size: 1.36em; font-weight: 700; line-height: 1.3; letter-spacing: -.012em; text-wrap: balance; }
.ape-blocks [data-type="h3"] > .ape-blocks-t { font-size: 1.12em; font-weight: 660; line-height: 1.35; text-wrap: balance; }

.ape-blocks .ape-blocks-mark { display: grid; place-items: center; width: 22px; height: calc(1.55em + 6px); color: var(--ape-blocks-ink); }
.ape-blocks [data-type="bullet"] .ape-blocks-mark::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ape-blocks [data-type="num"] .ape-blocks-mark { font-variant-numeric: tabular-nums; font-weight: 560; justify-items: end; padding-right: 2px; }
.ape-blocks .ape-blocks-check {
  display: grid; place-items: center; width: 17px; height: 17px; margin-top: calc((1.55em + 6px - 17px) / 2); border-radius: 5px;
  box-shadow: inset 0 0 0 1.5px var(--ape-blocks-faint); color: var(--ape-blocks-paper);
  transition: background .2s var(--ape-blocks-ease), box-shadow .2s, transform .25s var(--ape-blocks-spring);
  & svg { width: 13px; height: 13px; stroke-width: 2.4; stroke-dasharray: 16; stroke-dashoffset: 16; transition: stroke-dashoffset .28s var(--ape-blocks-ease) .04s; }
  &:hover { box-shadow: inset 0 0 0 1.5px var(--ape-blocks-accent); }
  &:active { transform: scale(.86); }
  &[aria-checked="true"] { background: var(--ape-blocks-accent); box-shadow: inset 0 0 0 1.5px var(--ape-blocks-accent); }
  &[aria-checked="true"] svg { stroke-dashoffset: 0; }
}
.ape-blocks [data-type="todo"] > .ape-blocks-t {
  text-decoration: line-through 1.5px transparent;
  transition: color .25s var(--ape-blocks-ease), text-decoration-color .3s var(--ape-blocks-ease);
}
.ape-blocks [data-type="todo"]:has([aria-checked="true"]) > .ape-blocks-t { color: var(--ape-blocks-faint); text-decoration-color: color-mix(in oklch, var(--ape-blocks-ink) 45%, transparent); }

.ape-blocks [data-type="quote"] > .ape-blocks-t {
  border-left: 3px solid var(--ape-blocks-ink); padding: 2px 0 2px 16px; margin: 4px 0;
  font-size: 1.08em; line-height: 1.5;
  & small { display: block; margin-top: 4px; font-size: .82em; color: var(--ape-blocks-mute); }
}
.ape-blocks [data-type="callout"] {
  & > .ape-blocks-t {
    display: block; margin: 6px 0; padding: 14px 16px 14px 46px; border-radius: 8px; position: relative;
    background: var(--ape-blocks-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-blocks-accent) 18%, transparent);
  }
  & > .ape-blocks-t::after {
    content: ""; position: absolute; left: 16px; top: 16px; width: 18px; height: 18px; border-radius: 50%;
    background:
      radial-gradient(circle at 50% 30%, var(--ape-blocks-paper) 0 1.4px, transparent 1.8px),
      linear-gradient(var(--ape-blocks-paper), var(--ape-blocks-paper)) 50% 70% / 2px 6px no-repeat,
      var(--ape-blocks-accent);
  }
  & > .ape-blocks-t:empty::before { color: var(--ape-blocks-faint); }
}
.ape-blocks [data-type="code"] > .ape-blocks-t {
  margin: 6px 0; padding: 14px 16px; border-radius: 8px; tab-size: 2;
  font: 13px/1.6 ui-monospace, Menlo, monospace; background: color-mix(in oklch, var(--ape-blocks-ink) 5%, var(--ape-blocks-bg));
  box-shadow: inset 0 0 0 1px var(--ape-blocks-line); overflow-x: auto; white-space: pre; overflow-wrap: normal;
}
.ape-blocks [data-type="divider"] {
  padding-block: 10px;
  & > .ape-blocks-t { min-height: 0; height: 1px; padding: 0; background: var(--ape-blocks-line2); margin-top: 11px; }
  & > .ape-blocks-t::before { display: none; }
  & > .ape-blocks-gut { top: 9px; }
}
.ape-blocks [data-type="divider"]:focus-within > .ape-blocks-t,
.ape-blocks [data-type="divider"].is-sel > .ape-blocks-t { background: var(--ape-blocks-accent); }

.ape-blocks .ape-blocks-tail {
  display: block; width: 100%; text-align: left; padding: 14px 2px; margin-top: 8px; color: var(--ape-blocks-faint); font-size: 13.5px;
  border-radius: 6px; transition: color .15s;
  &:hover { color: var(--ape-blocks-mute); }
