.ape-code {
  /* theme: override these four to re-skin */
  --ape-code-bg: oklch(0.215 0.011 68);
  --ape-code-ink: oklch(0.885 0.018 85);
  --ape-code-accent: oklch(0.8 0.135 78);
  --ape-code-chrome: oklch(0.18 0.01 66);

  /* syntax */
  --ape-code-kw: oklch(0.74 0.12 28);
  --ape-code-str: oklch(0.8 0.095 132);
  --ape-code-num: oklch(0.8 0.1 55);
  --ape-code-fn: oklch(0.87 0.085 95);
  --ape-code-ty: oklch(0.78 0.075 190);
  --ape-code-com: oklch(0.6 0.025 85);
  --ape-code-cn: oklch(0.82 0.09 70);
  --ape-code-err: oklch(0.68 0.19 25);
  --ape-code-warn: oklch(0.82 0.15 85);
  --ape-code-info: oklch(0.74 0.09 230);

  --ape-code-line: color-mix(in oklch, var(--ape-code-ink) 9%, transparent);
  --ape-code-line2: color-mix(in oklch, var(--ape-code-ink) 16%, transparent);
  --ape-code-mute: color-mix(in oklch, var(--ape-code-ink) 62%, var(--ape-code-bg));
  --ape-code-faint: color-mix(in oklch, var(--ape-code-ink) 36%, var(--ape-code-bg));
  --ape-code-hover: color-mix(in oklch, var(--ape-code-ink) 7%, transparent);
  --ape-code-tint: color-mix(in oklch, var(--ape-code-accent) 16%, transparent);
  --ape-code-raised: color-mix(in oklch, var(--ape-code-ink) 6%, var(--ape-code-bg));
  --ape-code-lh: 20px;
  --ape-code-cw: 7.8px;
  --ape-code-mono: 13px/var(--ape-code-lh) ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --ape-code-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-code-out: cubic-bezier(.32, .72, 0, 1);
  --ape-code-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 1 24%, 1.08 30%, 1.07 36%, 1.02 45%, 0.995 56%, 1);

  position: relative; width: 100%; height: var(--ape-code-h, 680px);
  container-type: inline-size; container-name: ape-code;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-code-bg); color: var(--ape-code-ink); color-scheme: dark;
  accent-color: var(--ape-code-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--ape-code-ink) 14%, black);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 1.5px solid var(--ape-code-accent); outline-offset: -1.5px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & p, & ul, & ol, & dl, & dd, & pre { margin: 0; }
  & ul, & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 500 10.5px/1 ui-monospace, Menlo, monospace; padding: 2px 5px 3px; border-radius: 4px;
    background: var(--ape-code-hover); box-shadow: inset 0 -1px 0 var(--ape-code-line2); color: var(--ape-code-mute);
  }
}

/* ── shell ──────────────────────────────────────────── */
.ape-code .ape-code-app {
  --ape-code-sw: 236px;
  height: 100%; display: grid;
  grid-template-columns: 46px var(--ape-code-sw) minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) 26px;
  grid-template-areas: "act side main" "status status status";
  transition: grid-template-columns .34s var(--ape-code-out);
}
.ape-code.is-noside .ape-code-app { --ape-code-sw: 0px; }
.ape-code .ape-code-nav { display: none; grid-area: nav; }

.ape-code .ape-code-act {
  grid-area: act; position: relative; display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 6px 0;
  background: var(--ape-code-chrome); border-right: 1px solid var(--ape-code-line);
  & > button { position: relative; display: grid; place-items: center; width: 46px; height: 44px; color: var(--ape-code-faint); transition: color .15s; }
  & > button svg { width: 22px; height: 22px; stroke-width: 1.4; }
  & > button:hover, & > button[aria-selected="true"] { color: var(--ape-code-ink); }
  & .ape-code-actfill { flex: 1; }
  & .ape-code-actk svg { width: 20px; height: 20px; }
}
.ape-code .ape-code-actbar {
  position: absolute; left: 0; top: 6px; width: 2px; height: 44px; border-radius: 0 2px 2px 0; background: var(--ape-code-accent);
  transform: translateY(calc(var(--ape-code-ai, 0) * 46px)); transition: transform .42s var(--ape-code-spring), opacity .2s;
}
.ape-code.is-noside .ape-code-actbar { opacity: 0; }
.ape-code .ape-code-badge {
  position: absolute; right: 7px; bottom: 7px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px;
  font: 700 10px/16px system-ui, sans-serif; text-align: center; font-variant-numeric: tabular-nums;
  background: var(--ape-code-accent); color: var(--ape-code-chrome);
  transition: scale .3s var(--ape-code-spring);
  @starting-style { scale: 0; }
}

/* ── side bar ───────────────────────────────────────── */
.ape-code .ape-code-side {
  grid-area: side; min-width: 0; min-height: 0; overflow: hidden; background: var(--ape-code-chrome);
  border-right: 1px solid var(--ape-code-line);
}
.ape-code .ape-code-pane {
  width: 236px; height: 100%; display: flex; flex-direction: column; min-height: 0; overflow-y: auto; scrollbar-width: thin;
  scrollbar-color: var(--ape-code-line2) transparent;
  &[hidden] { display: none; }
}
.ape-code .ape-code-ph {
  display: flex; align-items: center; justify-content: space-between; height: 36px; padding: 0 8px 0 16px; flex: none;
  font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--ape-code-mute);
}
.ape-code .ape-code-ib {
  display: grid; place-items: center; width: 26px; height: 26px; border-radius: 6px; color: var(--ape-code-mute);
  transition: background .15s, color .15s;
  &:hover { background: var(--ape-code-hover); color: var(--ape-code-ink); }
}
.ape-code .ape-code-proj { padding: 2px 16px 6px; font-size: 11.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--ape-code-ink); }
.ape-code .ape-code-tree { display: grid; grid-template-columns: minmax(0, 1fr); padding-bottom: 10px; }
.ape-code .ape-code-tree li { min-width: 0; }
.ape-code .ape-code-tree [role="group"] { display: grid; grid-template-columns: minmax(0, 1fr); }
.ape-code [role="treeitem"][aria-expanded="false"] > [role="group"] { display: none; }
.ape-code .ape-code-row {
  --d: 0;
  position: relative; display: flex; align-items: center; gap: 6px; height: 24px; padding: 0 10px 0 calc(10px + var(--d) * 14px);
  cursor: pointer; color: color-mix(in oklch, var(--ape-code-ink) 86%, var(--ape-code-chrome)); white-space: nowrap; user-select: none;
  &:hover { background: var(--ape-code-hover); }
  & .ape-code-chev { width: 12px; height: 12px; color: var(--ape-code-faint); transition: transform .2s var(--ape-code-out); }
  & .ape-code-fname { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
  & .ape-code-git { font: 600 11px/1 ui-monospace, Menlo, monospace; color: var(--ape-code-warn); }
  & .ape-code-pn { font: 600 10.5px/1 ui-monospace, Menlo, monospace; min-width: 14px; height: 14px; border-radius: 7px; display: grid; place-items: center; padding: 0 4px; }
  & .ape-code-pn.is-e { background: var(--ape-code-err); color: var(--ape-code-chrome); }
  & .ape-code-pn.is-w { color: var(--ape-code-warn); }
}
.ape-code [role="treeitem"][aria-expanded="true"] > .ape-code-row .ape-code-chev { transform: rotate(90deg); }
.ape-code [role="treeitem"][aria-selected="true"] > .ape-code-row {
  background: color-mix(in oklch, var(--ape-code-accent) 13%, var(--ape-code-chrome)); color: var(--ape-code-ink);
}
.ape-code [role="treeitem"]:focus-visible { outline: none; }
.ape-code [role="treeitem"]:focus-visible > .ape-code-row { box-shadow: inset 0 0 0 1px var(--ape-code-accent); }
.ape-code [role="treeitem"].is-dirty > .ape-code-row .ape-code-fname { color: var(--ape-code-warn); }
.ape-code .ape-code-fi {
  display: grid; place-items: center; width: 16px; height: 16px; flex: none; border-radius: 3px;
  font: 800 7.5px/1 ui-monospace, Menlo, monospace; letter-spacing: -.02em;
  &.is-ts { color: var(--ape-code-ty); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-code-ty) 55%, transparent); }
  &.is-json { color: var(--ape-code-cn); font-size: 9px; }
  &.is-md { color: var(--ape-code-info); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-code-info) 50%, transparent); }
  &.is-dir { color: var(--ape-code-mute); }
  &.is-dir svg { width: 15px; height: 15px; }
}

.ape-code .ape-code-sfield {
  display: flex; align-items: center; margin: 0 12px 8px; height: 28px; padding: 0 4px 0 8px; border-radius: 6px;
  background: var(--ape-code-bg); box-shadow: inset 0 0 0 1px var(--ape-code-line2);
  & input { flex: 1; min-width: 0; border: 0; outline: none; background: none; font-size: 12.5px; }
  & input::-webkit-search-cancel-button { display: none; }
  &:has(input:focus) { box-shadow: inset 0 0 0 1px var(--ape-code-accent); }
}
.ape-code .ape-code-cs {
  width: 22px; height: 20px; border-radius: 4px; font: 600 11px/1 system-ui, sans-serif; color: var(--ape-code-faint);
  &[aria-pressed="true"] { background: var(--ape-code-tint); color: var(--ape-code-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-code-accent) 50%, transparent); }
}
.ape-code .ape-code-scount { padding: 0 16px 6px; font-size: 11.5px; color: var(--ape-code-mute); }
.ape-code .ape-code-results {
  & .ape-code-rfile { display: flex; align-items: center; gap: 6px; padding: 4px 12px; font-size: 12.5px; }
  & .ape-code-rfile small { color: var(--ape-code-faint); font-size: 11px; }
  & .ape-code-rfile b { margin-left: auto; font: 600 10.5px/16px system-ui; min-width: 18px; text-align: center; border-radius: 8px; background: var(--ape-code-hover); color: var(--ape-code-mute); }
  & button {
    display: block; width: 100%; text-align: left; padding: 3px 12px 3px 34px; font: 12px/1.5 ui-monospace, Menlo, monospace;
    color: var(--ape-code-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    &:hover { background: var(--ape-code-hover); color: var(--ape-code-ink); }
    & mark { background: color-mix(in oklch, var(--ape-code-accent) 30%, transparent); color: var(--ape-code-ink); border-radius: 2px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--ape-code-accent) 55%, transparent); }
  }
}
.ape-code .ape-code-commit {
  display: grid; gap: 8px; padding: 0 12px 10px;
  & textarea {
    resize: none; border: 0; outline: none; border-radius: 6px; padding: 7px 9px; font-size: 12.5px; line-height: 1.4;
    background: var(--ape-code-bg); box-shadow: inset 0 0 0 1px var(--ape-code-line2);
    &:focus { box-shadow: inset 0 0 0 1px var(--ape-code-accent); }
    &.is-shake { animation: ape-code-shake .36s var(--ape-code-ease); }
  }
}
@keyframes ape-code-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }
.ape-code .ape-code-cbtn {
  display: flex; align-items: center; justify-content: center; gap: 6px; height: 28px; border-radius: 6px; font-weight: 600; font-size: 12.5px;
  background: var(--ape-code-accent); color: var(--ape-code-chrome); transition: filter .15s, transform .15s var(--ape-code-ease);
  &:hover { filter: brightness(1.07); }
  &:active { transform: scale(.98); }
  &:disabled { opacity: .4; cursor: default; filter: none; transform: none; }
}
.ape-code .ape-code-unsaved {
  margin: 0 12px 8px; padding: 7px 9px; border-radius: 6px; font-size: 12px; color: var(--ape-code-warn);
  background: color-mix(in oklch, var(--ape-code-warn) 9%, transparent);
  & button { text-decoration: underline; text-underline-offset: 2px; }
  &[hidden] { display: none; }
}
.ape-code .ape-code-sec { padding: 8px 16px 4px; font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--ape-code-mute); }
.ape-code .ape-code-changes {
  & button { display: flex; align-items: center; gap: 7px; width: 100%; height: 26px; padding: 0 12px 0 16px; text-align: left; font-size: 12.5px; }
  & button:hover { background: var(--ape-code-hover); }
  & small { color: var(--ape-code-faint); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .ape-code-pm { margin-left: auto; font: 600 11px/1 ui-monospace, Menlo, monospace; display: flex; gap: 6px; }
  & .ape-code-pm i { font-style: normal; color: var(--ape-code-str); }
  & .ape-code-pm i + i { color: var(--ape-code-err); }
  & .ape-code-m { font: 700 11px/1 ui-monospace, Menlo, monospace; color: var(--ape-code-warn); width: 12px; text-align: center; }
  & li.ape-code-none { padding: 4px 16px; font-size: 12px; color: var(--ape-code-faint); }
}
.ape-code .ape-code-log {
  padding: 0 0 12px;
  & li { position: relative; display: grid; grid-template-columns: 14px 1fr; column-gap: 8px; padding: 3px 12px 3px 16px; font-size: 12px; }
  & li::before { content: ""; width: 7px; height: 7px; margin: 5px 0 0 3px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ape-code-mute); }
  & li:first-child::before { background: var(--ape-code-accent); box-shadow: none; }
  & li:not(:last-child)::after { content: ""; position: absolute; left: 22px; top: 15px; bottom: -6px; width: 1px; background: var(--ape-code-line2); }
  & code { display: block; font: 11px/1.4 ui-monospace, Menlo, monospace; color: var(--ape-code-faint); }
  & li.is-new { animation: ape-code-drop .5s var(--ape-code-out); }
}
@keyframes ape-code-drop { from { opacity: 0; translate: 0 -8px; } }

/* ── main / editor ──────────────────────────────────── */
.ape-code .ape-code-main {
  --ape-code-ph: 190px;
  grid-area: main; min-width: 0; min-height: 0; display: grid;
  grid-template-rows: 36px 26px minmax(0, 1fr) 5px var(--ape-code-ph);
  transition: grid-template-rows .34s var(--ape-code-out);
}
.ape-code.is-resizing .ape-code-main { transition: none; }
.ape-code.is-nopanel .ape-code-main { --ape-code-ph: 0px; }
.ape-code.is-nopanel .ape-code-split { pointer-events: none; }
.ape-code .ape-code-tabs {
  display: flex; min-width: 0; overflow-x: auto; overflow-y: hidden; background: var(--ape-code-chrome); scrollbar-width: none;
  box-shadow: inset 0 -1px 0 var(--ape-code-line);
}
.ape-code .ape-code-tab {
  position: relative; display: flex; align-items: center; gap: 7px; height: 36px; padding: 0 6px 0 12px; flex: none;
  color: var(--ape-code-mute); border-right: 1px solid var(--ape-code-line); white-space: nowrap; cursor: pointer; font-size: 12.5px;
  transition: background .15s, color .15s, opacity .22s var(--ape-code-ease), translate .3s var(--ape-code-out);
  @starting-style { opacity: 0; translate: 0 8px; }
  &:hover { background: color-mix(in oklch, var(--ape-code-ink) 3%, var(--ape-code-chrome)); }
  &[aria-selected="true"] { background: var(--ape-code-bg); color: var(--ape-code-ink); box-shadow: inset 0 2px 0 var(--ape-code-accent); }
  &:focus-visible { outline-offset: -2px; }
  & .ape-code-x {
    display: grid; place-items: center; width: 20px; height: 20px; border-radius: 5px; color: var(--ape-code-faint); position: relative;
    & svg { width: 12px; height: 12px; stroke-width: 1.8; }
    &:hover { background: var(--ape-code-hover); color: var(--ape-code-ink); }
  }
  &:not(:hover, [aria-selected="true"]) .ape-code-x { opacity: 0; }
  &.is-dirty .ape-code-x svg { opacity: 0; }
  &.is-dirty .ape-code-x::after { content: ""; position: absolute; width: 8px; height: 8px; border-radius: 50%; background: var(--ape-code-ink); }
  &.is-dirty .ape-code-x { opacity: 1; }
  &.is-dirty .ape-code-x:hover svg { opacity: 1; }
  &.is-dirty .ape-code-x:hover::after { opacity: 0; }
}
.ape-code .ape-code-crumbs {
  display: flex; align-items: center; gap: 4px; padding: 0 14px; min-width: 0; overflow: hidden; white-space: nowrap;
  font-size: 12px; color: var(--ape-code-mute); background: var(--ape-code-bg);
  & svg { width: 11px; height: 11px; color: var(--ape-code-faint); }
  & b { font-weight: 500; color: var(--ape-code-ink); }
  & .ape-code-sym { color: var(--ape-code-fn); display: inline-flex; align-items: center; gap: 4px; }
  & .ape-code-sym i { font: 700 9px/1 ui-monospace, Menlo, monospace; font-style: normal; color: var(--ape-code-kw); }
}

.ape-code .ape-code-ed { position: relative; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 86px; background: var(--ape-code-bg); }
.ape-code.is-nomini .ape-code-ed { grid-template-columns: minmax(0, 1fr) 0; }
.ape-code .ape-code-scroll {
  min-width: 0; min-height: 0; overflow: auto; overscroll-behavior: contain; position: relative;
  scrollbar-width: thin; scrollbar-color: var(--ape-code-line2) transparent;
}
.ape-code .ape-code-sizer { display: grid; grid-template-columns: max-content minmax(max-content, 1fr); min-width: 100%; min-height: 100%; }
.ape-code .ape-code-gutter {
  position: sticky; left: 0; z-index: 2; min-width: 58px; padding: 10px 16px 0 18px; text-align: right;
  font: var(--ape-code-mono); font-size: 12px; color: var(--ape-code-faint); background: var(--ape-code-bg);
  font-variant-numeric: tabular-nums; user-select: none;
  & span { display: block; height: var(--ape-code-lh); position: relative; }
  & span.is-cur { color: var(--ape-code-ink); }
  & span[data-sev]::before { content: ""; position: absolute; left: -12px; top: 7px; width: 6px; height: 6px; border-radius: 50%; }
  & span[data-sev="e"]::before { background: var(--ape-code-err); }
  & span[data-sev="w"]::before { background: var(--ape-code-warn); }
  & span[data-sev="i"]::before { box-shadow: inset 0 0 0 1.5px var(--ape-code-info); }
}
.ape-code .ape-code-col { position: relative; padding: 10px 48px calc(var(--ape-code-lh) * 10) 12px; }
.ape-code .ape-code-curline {
  position: absolute; left: 0; right: 0; height: var(--ape-code-lh);
  top: calc(10px + var(--ape-code-cl, 0) * var(--ape-code-lh));
  background: color-mix(in oklch, var(--ape-code-ink) 4.5%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklch, var(--ape-code-ink) 5%, transparent), inset 0 -1px 0 color-mix(in oklch, var(--ape-code-ink) 5%, transparent);
  transition: top .09s linear;
}
.ape-code .ape-code-ed:not(:focus-within) .ape-code-curline { opacity: .45; }
.ape-code .ape-code-hl, .ape-code .ape-code-ta {
  font: var(--ape-code-mono); tab-size: 2; letter-spacing: 0; white-space: pre; font-variant-ligatures: none; font-feature-settings: "liga" 0, "calt" 0;
}
.ape-code .ape-code-hl {
  position: relative; color: var(--ape-code-ink); pointer-events: none; min-height: var(--ape-code-lh);
  & .k { color: var(--ape-code-kw); }
  & .s { color: var(--ape-code-str); }
  & .n { color: var(--ape-code-num); }
  & .f { color: var(--ape-code-fn); }
  & .t { color: var(--ape-code-ty); }
  & .cn { color: var(--ape-code-cn); }
  & .p { color: color-mix(in oklch, var(--ape-code-ink) 82%, var(--ape-code-ty)); }
  & .o { color: color-mix(in oklch, var(--ape-code-kw) 55%, var(--ape-code-ink)); }
  & .c { color: var(--ape-code-com); font-style: italic; }
  & .todo { color: var(--ape-code-chrome); background: color-mix(in oklch, var(--ape-code-info) 80%, transparent); border-radius: 2px; font-style: normal; font-weight: 700; }
  & .key { color: var(--ape-code-ty); }
  & .h { color: var(--ape-code-fn); font-weight: 700; }
  & .b0 { color: var(--ape-code-fn); }
  & .b1 { color: oklch(0.76 0.11 340); }
  & .b2 { color: var(--ape-code-ty); }
  & .sq-e, & .sq-w, & .sq-i { text-decoration: underline wavy; text-decoration-skip-ink: none; text-underline-offset: 3px; text-decoration-thickness: 1px; }
  & .sq-e { text-decoration-color: var(--ape-code-err); }
  & .sq-w { text-decoration-color: var(--ape-code-warn); }
  & .sq-i { text-decoration-color: var(--ape-code-info); text-decoration-style: dotted; }
  & mark { background: color-mix(in oklch, var(--ape-code-accent) 26%, transparent); color: inherit; border-radius: 2px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--ape-code-accent) 50%, transparent); }
}
.ape-code .ape-code-ta {
  position: absolute; inset: 0; z-index: 1; display: block; width: 100%; height: 100%; margin: 0;
  padding: 10px 48px calc(var(--ape-code-lh) * 10) 12px;
  border: 0; outline: none; resize: none; overflow: hidden; background: transparent;
  color: transparent; caret-color: var(--ape-code-accent); -webkit-text-fill-color: transparent;
  &::selection { background: color-mix(in oklch, var(--ape-code-accent) 26%, transparent); }
}
.ape-code .ape-code-bm {
  position: absolute; display: none; width: var(--ape-code-cw); height: var(--ape-code-lh); border-radius: 2px; pointer-events: none;
  left: calc(12px + var(--x, 0) * var(--ape-code-cw)); top: calc(10px + var(--y, 0) * var(--ape-code-lh));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-code-ink) 45%, transparent);
  background: color-mix(in oklch, var(--ape-code-ink) 8%, transparent);
  &.is-on { display: block; }
}
.ape-code .ape-code-mini {
  position: relative; min-height: 0; overflow: hidden; border-left: 1px solid var(--ape-code-line); cursor: default; touch-action: none;
  & canvas { display: block; width: 100%; height: 100%; }
