const SAVED = {"src/harmonics.ts": "import { Station, Constituent } from './stations';

/** Angular speed of each constituent, in degrees per hour. */
export const SPEED: Record<string, number> = {
  M2: 28.984104,
  S2: 30.0,
  N2: 28.43973,
  K1: 15.041069,
  O1: 13.943036,
};

const RAD = Math.PI / 180;
const HOUR = 3_600_000;

export interface Prediction {
  time: Date;
  height: number;
}

/** Height above chart datum, in metres, at one moment. */
export function heightAt(station: Station, time: Date): number {
  const hours = (time.getTime() - station.epoch.getTime()) / HOUR;
  let h = station.datum;
  for (const c of station.constituents) {
    const speed = SPEED[c.name];
    if (speed === undefined) continue;
    h += c.amplitude * Math.cos((speed * hours - c.phase) * RAD);
  }
  return h;
}

/** Sample one UTC day at a fixed step and keep the turning points. */
export function extremes(station: Station, day: Date, stepMin = 6): Prediction[] {
  const out: Prediction[] = [];
  const start = new Date(day);
  start.setUTCHours(0, 0, 0, 0);
  let prev = heightAt(station, start);
  let rising: boolean | null = null;
  for (let m = stepMin; m <= 24 * 60; m += stepMin) {
    const t = new Date(start.getTime() + m * 60_000);
    const h = heightAt(station, t);
    const up = h > prev;
    if (rising !== null && up !== rising) {
      out.push({ time: new Date(t.getTime() - stepMin * 60_000), height: prev });
    }
    rising = up;
    prev = h;
  }
  return out;
}

// TODO: interpolate the turning point instead of snapping to the step
export function range(preds: Prediction[]): number {
  const hs = preds.map(p => p.height);
  return Math.max(...hs) - Math.min(...hs);
}
