", "src/format.ts": "import { Prediction } from './harmonics';

const pad = (n: number) => String(n).padStart(2, '0');

export function clock(d: Date): string {
  return `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`;
}

export function metres(h: number, digits = 2): string {
  return `${h.toFixed(digits)} m`;
}

export function table(preds: Prediction[]): string {
  return preds
    .map(p => `${clock(p.time)}  ${metres(p.height)}`)
    .join('\n');
}
