import { heightAt, extremes, range } from '../src/harmonics';
import { GULLHAVEN } from '../src/stations';

const DAY = new Date(Date.UTC(2026, 9, 2));

describe('heightAt', () => {
  it('returns the datum when every amplitude is zero', () => {
    const flat = { ...GULLHAVEN, constituents: [] };
    expect(heightAt(flat, DAY)).toBe(GULLHAVEN.datum);
  });

  it('stays within the datum plus or minus the summed amplitudes', () => {
    const sum = GULLHAVEN.constituents.reduce((s, c) => s + c.amplitude, 0);
    const h = heightAt(GULLHAVEN, DAY);
    expect(Math.abs(h - GULLHAVEN.datum)).toBeLessThanOrEqual(sum);
  });
});

describe('extremes', () => {
  it('finds two highs and two lows on a semidiurnal day', () => {
    expect(extremes(GULLHAVEN, DAY)).toHaveLength(4);
  });

  it('returns turning points in time order', () => {
    const t = extremes(GULLHAVEN, DAY).map(p => p.time.getTime());
    expect(t).toEqual([...t].sort((a, b) => a - b));
  });
});

describe('range', () => {
  it('is never negative', () => {
    expect(range(extremes(GULLHAVEN, DAY))).toBeGreaterThanOrEqual(0);
  });
});
