  const k = e.key.toLowerCase();
  if (mod(e) && k === 'p') { e.preventDefault(); openPal(e.shiftKey ? '>' : ''); }
  else if (e.ctrlKey && !e.metaKey && e.shiftKey && k === 'g') { e.preventDefault(); showSide('scm'); }
  else if (e.ctrlKey && !e.metaKey && k === 'g') { e.preventDefault(); openPal(':'); }
  else if (mod(e) && e.altKey && e.code === 'KeyS') { e.preventDefault(); saveAll(); }
  else if (mod(e) && !e.shiftKey && k === 's') { e.preventDefault(); save(); }
  else if (mod(e) && !e.shiftKey && k === 'b') { e.preventDefault(); setSide(!S.sideOpen); }
  else if (mod(e) && !e.shiftKey && k === 'j') { e.preventDefault(); setPanel(!S.panel); }
  else if (mod(e) && e.shiftKey && k === 'e') { e.preventDefault(); showSide('explorer'); }
  else if (mod(e) && e.shiftKey && k === 'f') { e.preventDefault(); showSide('search'); sIn.focus(); sIn.select(); }
  else if (e.altKey && !mod(e) && e.code === 'KeyW') { e.preventDefault(); if (S.active) closeTab(S.active); }
  else if (e.key === 'Escape' && !pal.hidden) { e.preventDefault(); closePal(); }
});

/* ── sizing ────────────────────────────────────────── */
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const was = S.narrow;
  S.narrow = root.clientWidth < 760;
  if (S.narrow !== was && !S.narrow) setView('editor');
  drawMiniSoon();
});
ro.observe(root);
ro.observe(mini);

/* ── boot ──────────────────────────────────────────── */
measure();
prompt();
echo('git status', true);
print('On branch <span class="acc">main</span>', true);
print('Changes not staged for commit:', true);
changed().forEach(p => print('        <span class="bad">modified:   ' + esc(p) + '</span>', true));
echo('npm test', true);
testLines().L.forEach(l => print(l, true));
showSide('explorer');
setPanel(true);
load();
renderTabs(); renderTree(); renderScm(); renderProblems(); renderSearch();

