.ape-sheet {
  /* theme: override these four to re-skin */
  --ape-sheet-bg: oklch(0.992 0.003 150);
  --ape-sheet-ink: oklch(0.26 0.025 165);
  --ape-sheet-accent: oklch(0.55 0.12 156);
  --ape-sheet-chrome: oklch(0.966 0.009 150);

  --ape-sheet-r0: oklch(0.56 0.16 258);
  --ape-sheet-r1: oklch(0.6 0.18 28);
  --ape-sheet-r2: oklch(0.54 0.16 318);
  --ape-sheet-r3: oklch(0.66 0.14 72);
  --ape-sheet-r4: oklch(0.58 0.11 200);

  --ape-sheet-grid: color-mix(in oklch, var(--ape-sheet-ink) 10%, var(--ape-sheet-bg));
  --ape-sheet-line: color-mix(in oklch, var(--ape-sheet-ink) 11%, transparent);
  --ape-sheet-line2: color-mix(in oklch, var(--ape-sheet-ink) 19%, transparent);
  --ape-sheet-mute: color-mix(in oklch, var(--ape-sheet-ink) 60%, var(--ape-sheet-bg));
  --ape-sheet-faint: color-mix(in oklch, var(--ape-sheet-ink) 38%, var(--ape-sheet-bg));
  --ape-sheet-hover: color-mix(in oklch, var(--ape-sheet-ink) 6%, transparent);
  --ape-sheet-tint: color-mix(in oklch, var(--ape-sheet-accent) 12%, var(--ape-sheet-bg));
  --ape-sheet-tint2: color-mix(in oklch, var(--ape-sheet-accent) 22%, var(--ape-sheet-bg));
  --ape-sheet-deep: color-mix(in oklch, var(--ape-sheet-accent) 75%, var(--ape-sheet-ink));
  --ape-sheet-err: oklch(0.55 0.19 27);
  --ape-sheet-rh: 46px;
  --ape-sheet-ch: 26px;
  --ape-sheet-row: 28px;
  --ape-sheet-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-sheet-out: cubic-bezier(.32, .72, 0, 1);
  --ape-sheet-spring: linear(0, 0.14 5%, 0.5 12%, 0.86 20%, 1.02 27%, 1.05 33%, 1.03 40%, 1.005 52%, 1);

  position: relative; width: 100%; height: var(--ape-sheet-h, 680px);
  container-type: inline-size; container-name: ape-sheet;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-sheet-bg); color: var(--ape-sheet-ink); color-scheme: light;
  accent-color: var(--ape-sheet-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px var(--ape-sheet-line2);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--ape-sheet-accent); outline-offset: 1px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & p, & dl, & dd, & ol { margin: 0; }
  & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 600 10.5px/1 ui-monospace, Menlo, monospace; padding: 2px 5px 3px; border-radius: 4px; color: var(--ape-sheet-mute);
    background: var(--ape-sheet-bg); box-shadow: inset 0 0 0 1px var(--ape-sheet-line2), inset 0 -1px 0 var(--ape-sheet-line2);
  }
}

/* ── shell ──────────────────────────────────────────── */
.ape-sheet .ape-sheet-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 264px;
  grid-template-rows: 52px 38px minmax(0, 1fr) 36px;
  grid-template-areas: "top top" "fbar insp" "main insp" "foot foot";
}
.ape-sheet .ape-sheet-top {
  grid-area: top; display: flex; align-items: center; gap: 14px; padding: 0 12px 0 14px; min-width: 0;
  background: var(--ape-sheet-chrome); border-bottom: 1px solid var(--ape-sheet-line);
}
.ape-sheet .ape-sheet-doc {
  display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1;
  & b { display: block; font-size: 14px; font-weight: 680; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11.5px; color: var(--ape-sheet-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .2s; }
  & small.is-busy { color: var(--ape-sheet-deep); }
  & > div { min-width: 0; }
}
.ape-sheet .ape-sheet-logo {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; flex: none;
  background: var(--ape-sheet-accent); color: var(--ape-sheet-bg);
  & svg { width: 18px; height: 18px; stroke-width: 1.6; }
}
.ape-sheet .ape-sheet-tools { display: flex; align-items: center; gap: 2px; min-width: 0; overflow-x: auto; scrollbar-width: none; }
.ape-sheet .ape-sheet-sep { width: 1px; height: 20px; margin: 0 6px; background: var(--ape-sheet-line2); flex: none; }
.ape-sheet .ape-sheet-tb {
  display: inline-flex; align-items: center; justify-content: center; gap: 5px; min-width: 30px; height: 30px; padding: 0 6px; border-radius: 7px; flex: none;
  color: var(--ape-sheet-mute); font-weight: 600; font-size: 13px;
  transition: background .15s, color .15s, transform .15s var(--ape-sheet-ease);
  & svg { width: 15px; height: 15px; }
  &.ape-sheet-tt svg { width: 11px; height: 11px; margin-left: -4px; stroke-width: 2; }
  &:hover { background: var(--ape-sheet-hover); color: var(--ape-sheet-ink); }
  &:active { transform: scale(.94); }
  &[aria-pressed="true"] { background: var(--ape-sheet-tint2); color: var(--ape-sheet-deep); }
  &:disabled { opacity: .35; pointer-events: none; }
  &.ape-sheet-wide { padding: 0 9px 0 7px; font-weight: 550; font-size: 12.5px; }
}
.ape-sheet .ape-sheet-cellbtn { display: none !important; }

/* ── formula bar ────────────────────────────────────── */
.ape-sheet .ape-sheet-fbar {
  grid-area: fbar; display: grid; grid-template-columns: 92px auto minmax(0, 1fr); align-items: center;
  border-bottom: 1px solid var(--ape-sheet-line); background: var(--ape-sheet-bg); min-width: 0;
}
.ape-sheet .ape-sheet-name {
  height: 100%; border: 0; outline: none; padding: 0 12px; background: none; border-right: 1px solid var(--ape-sheet-line);
  font: 600 12.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; min-width: 0;
  &:focus { background: var(--ape-sheet-tint); box-shadow: inset 0 -2px 0 var(--ape-sheet-accent); }
}
.ape-sheet .ape-sheet-fx {
  padding: 0 10px; color: var(--ape-sheet-faint); font: italic 600 14px/1 Georgia, serif; letter-spacing: -.04em;
  & i { font-style: italic; }
}
.ape-sheet .ape-sheet-field { position: relative; height: 100%; min-width: 0; overflow: hidden; }
.ape-sheet .ape-sheet-mirror, .ape-sheet .ape-sheet-field input, .ape-sheet .ape-sheet-editor input {
  font: 13px/1 ui-monospace, "SF Mono", Menlo, monospace; letter-spacing: 0; white-space: pre; font-variant-ligatures: none;
}
.ape-sheet .ape-sheet-mirror {
  position: absolute; inset: 0; display: flex; align-items: center; padding: 0 10px; pointer-events: none; color: var(--ape-sheet-ink);
  & > span { display: block; translate: var(--ape-sheet-sx, 0) 0; }
  & .r0 { color: var(--ape-sheet-r0); } & .r1 { color: var(--ape-sheet-r1); } & .r2 { color: var(--ape-sheet-r2); } & .r3 { color: var(--ape-sheet-r3); } & .r4 { color: var(--ape-sheet-r4); }
  & .fn { color: var(--ape-sheet-deep); font-weight: 700; }
  & .str { color: oklch(0.52 0.12 60); }
  & .num { color: oklch(0.5 0.13 255); }
  & .op { color: var(--ape-sheet-mute); }
  & .bad { text-decoration: underline wavy var(--ape-sheet-err); }
}
.ape-sheet .ape-sheet-field input {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0; outline: none; padding: 0 10px; background: none;
  color: transparent; -webkit-text-fill-color: transparent; caret-color: var(--ape-sheet-ink);
  &::selection { background: color-mix(in oklch, var(--ape-sheet-accent) 25%, transparent); }
}
.ape-sheet .ape-sheet-field:has(input:focus) { box-shadow: inset 0 -2px 0 var(--ape-sheet-accent); }

/* ── grid ───────────────────────────────────────────── */
.ape-sheet .ape-sheet-main { grid-area: main; position: relative; min-width: 0; min-height: 0; }
.ape-sheet .ape-sheet-scroll {
  position: absolute; inset: 0; overflow: auto; overscroll-behavior: contain; outline: none;
  scrollbar-width: thin; scrollbar-color: var(--ape-sheet-line2) transparent; background: var(--ape-sheet-bg);
}
.ape-sheet .ape-sheet-cells {
  display: grid; width: max-content; grid-auto-rows: var(--ape-sheet-row);
  grid-template-rows: var(--ape-sheet-ch);
  font-variant-numeric: tabular-nums;
}
.ape-sheet .ape-sheet-cells [role="row"] { display: contents; }
.ape-sheet .ape-sheet-c {
  position: relative; display: flex; align-items: center; padding: 0 8px; overflow: hidden; white-space: nowrap; min-width: 0;
  border-right: 1px solid var(--ape-sheet-grid); border-bottom: 1px solid var(--ape-sheet-grid); cursor: cell; user-select: none;
  & > span { overflow: hidden; text-overflow: clip; }
  &.is-num { justify-content: flex-end; }
  &.is-b { font-weight: 700; }
  &.is-err { color: var(--ape-sheet-err); font-weight: 600; justify-content: center; }
  &.is-head { color: var(--ape-sheet-mute); font-weight: 600; font-size: 12px; letter-spacing: .01em; }
  &.is-sel { background: color-mix(in oklch, var(--ape-sheet-accent) 9%, transparent); }
  &.is-flash { animation: ape-sheet-flash .9s var(--ape-sheet-ease) both; animation-delay: calc(var(--d, 0) * 80ms); }
  &.is-flash > span { animation: ape-sheet-tick .45s var(--ape-sheet-out) both; animation-delay: calc(var(--d, 0) * 80ms); }
}
.ape-sheet.is-formulas .ape-sheet-c.is-f { justify-content: flex-start; font: 12px/1 ui-monospace, Menlo, monospace; color: var(--ape-sheet-deep); }
@keyframes ape-sheet-flash {
  0% { background: var(--ape-sheet-tint2); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-sheet-accent) 50%, transparent); }
  100% { background: transparent; box-shadow: inset 0 0 0 1px transparent; }
}
@keyframes ape-sheet-tick { from { opacity: .15; translate: 0 -5px; filter: blur(1px); } }
.ape-sheet .ape-sheet-h {
  position: sticky; z-index: 4; display: flex; align-items: center; justify-content: center; user-select: none;
  background: var(--ape-sheet-chrome); color: var(--ape-sheet-mute); font: 600 11.5px/1 system-ui, sans-serif; cursor: default;
  border-right: 1px solid var(--ape-sheet-grid); border-bottom: 1px solid var(--ape-sheet-grid);
  transition: background .15s, color .15s;
  &.is-col { top: 0; cursor: s-resize; }
  &.is-row { left: 0; cursor: e-resize; font-variant-numeric: tabular-nums; }
  &.is-corner { top: 0; left: 0; z-index: 6; cursor: pointer; }
  &.is-on { background: color-mix(in oklch, var(--ape-sheet-accent) 16%, var(--ape-sheet-chrome)); color: var(--ape-sheet-deep); }
  &.is-on.is-col { box-shadow: inset 0 -2px 0 var(--ape-sheet-accent); }
  &.is-on.is-row { box-shadow: inset -2px 0 0 var(--ape-sheet-accent); }
  &:hover { color: var(--ape-sheet-ink); }
  & .ape-sheet-rz { position: absolute; right: -4px; top: 0; bottom: 0; width: 8px; z-index: 2; cursor: col-resize; }
  & .ape-sheet-rz::after { content: ""; position: absolute; left: 3px; top: 5px; bottom: 5px; width: 2px; border-radius: 1px; background: var(--ape-sheet-accent); opacity: 0; transition: opacity .15s; }
  & .ape-sheet-rz:hover::after, & .ape-sheet-rz.is-drag::after { opacity: 1; }
}

/* overlays live in the scroller's content space, under the sticky headers */
.ape-sheet .ape-sheet-sel, .ape-sheet .ape-sheet-act, .ape-sheet .ape-sheet-fillbox, .ape-sheet .ape-sheet-refbox {
  position: absolute; left: 0; top: 0; pointer-events: none; z-index: 2;
  translate: var(--x, 0) var(--y, 0); width: var(--w, 0); height: var(--h, 0);
}
.ape-sheet .ape-sheet-sel {
  background: color-mix(in oklch, var(--ape-sheet-accent) 7%, transparent);
  box-shadow: inset 0 0 0 1px var(--ape-sheet-accent);
  transition: translate .18s var(--ape-sheet-spring), width .18s var(--ape-sheet-spring), height .18s var(--ape-sheet-spring);
}
.ape-sheet .ape-sheet-act {
  box-shadow: inset 0 0 0 2px var(--ape-sheet-accent); border-radius: 1px; z-index: 3;
  transition: translate .16s var(--ape-sheet-spring), width .16s var(--ape-sheet-spring), height .16s var(--ape-sheet-spring);
}
.ape-sheet .ape-sheet-handle {
  position: absolute; right: -4px; bottom: -4px; width: 8px; height: 8px; border-radius: 2px; pointer-events: auto; cursor: crosshair;
  background: var(--ape-sheet-accent); box-shadow: 0 0 0 1.5px var(--ape-sheet-bg); z-index: 4; touch-action: none;
  transition: scale .2s var(--ape-sheet-spring);
  &:hover { scale: 1.35; }
}
.ape-sheet.is-editing .ape-sheet-handle { display: none; }
.ape-sheet .ape-sheet-fillbox { display: none; box-shadow: inset 0 0 0 1.5px var(--ape-sheet-accent); outline: 1.5px dashed var(--ape-sheet-bg); outline-offset: -1.5px; z-index: 3; }
.ape-sheet .ape-sheet-fillbox.is-on { display: block; }
.ape-sheet .ape-sheet-refbox {
  --c: var(--ape-sheet-r0);
  border: 1.5px solid var(--c); background: color-mix(in oklch, var(--c) 9%, transparent); border-radius: 1px;
  transition: translate .14s var(--ape-sheet-out), width .14s var(--ape-sheet-out), height .14s var(--ape-sheet-out), opacity .15s;
  @starting-style { opacity: 0; }
  &::before, &::after { content: ""; position: absolute; width: 5px; height: 5px; background: var(--c); }
  &::before { left: -3px; top: -3px; }
  &::after { right: -3px; bottom: -3px; }
  &.is-point { border-style: dashed; animation: ape-sheet-march .6s linear infinite; }
}
@keyframes ape-sheet-march { to { border-color: color-mix(in oklch, var(--c) 55%, transparent); } }
.ape-sheet .ape-sheet-trace {
  position: absolute; left: 0; top: 0; z-index: 3; pointer-events: none; overflow: visible; width: 1px; height: 1px;
  & .tp { stroke: var(--ape-sheet-r0); stroke-width: 1.6; fill: none; }
  & .td { stroke: var(--ape-sheet-r1); stroke-width: 1.6; fill: none; stroke-dasharray: 4 3; }
  & .tb { fill: color-mix(in oklch, var(--ape-sheet-r0) 8%, transparent); stroke: var(--ape-sheet-r0); stroke-width: 1.2; }
  & .tdot { fill: var(--ape-sheet-r0); }
  & .tdot.d { fill: var(--ape-sheet-r1); }
  & path, & rect, & circle { animation: ape-sheet-draw .5s var(--ape-sheet-out) both; }
  & path { stroke-dasharray: 600; }
  & .td { stroke-dasharray: 4 3; animation-name: ape-sheet-fade; }
}
@keyframes ape-sheet-draw { from { stroke-dashoffset: 600; opacity: 0; } to { stroke-dashoffset: 0; opacity: 1; } }
@keyframes ape-sheet-fade { from { opacity: 0; } }

.ape-sheet .ape-sheet-editor {
  position: absolute; left: 0; top: 0; z-index: 5; translate: var(--x, 0) var(--y, 0); width: var(--w, 100px); height: var(--h, 28px);
  min-width: var(--w, 100px); background: var(--ape-sheet-bg); overflow: hidden;
  box-shadow: inset 0 0 0 2px var(--ape-sheet-accent), 0 6px 18px -8px color-mix(in oklch, var(--ape-sheet-ink) 40%, transparent);
  &[hidden] { display: none; }
  & .ape-sheet-mirror { padding: 0 8px; }
  & input {
    position: absolute; inset: 0; width: 100%; height: 100%; border: 0; outline: none; padding: 0 8px; background: none;
    color: transparent; -webkit-text-fill-color: transparent; caret-color: var(--ape-sheet-ink);
    &::selection { background: color-mix(in oklch, var(--ape-sheet-accent) 25%, transparent); }
  }
}

/* autocomplete + signature */
.ape-sheet .ape-sheet-ac, .ape-sheet .ape-sheet-sig {
  position: absolute; z-index: 30; left: 0; top: 0; translate: var(--x, 0) var(--y, 0);
  border-radius: 8px; background: var(--ape-sheet-bg);
  box-shadow: 0 0 0 1px var(--ape-sheet-line2), 0 18px 40px -16px color-mix(in oklch, var(--ape-sheet-ink) 45%, transparent);
  transition: opacity .14s var(--ape-sheet-ease);
  @starting-style { opacity: 0; }
  &[hidden] { display: none; }
}
.ape-sheet .ape-sheet-ac {
  width: 280px; padding: 4px;
  & .ape-sheet-opt {
    display: grid; grid-template-columns: auto 1fr; column-gap: 10px; align-items: baseline; padding: 6px 8px; border-radius: 6px; cursor: pointer;
    & b { font: 700 12px/1.2 ui-monospace, Menlo, monospace; color: var(--ape-sheet-deep); }
    & small { color: var(--ape-sheet-mute); font-size: 12px; }
    &[aria-selected="true"] { background: var(--ape-sheet-tint); }
  }
}
.ape-sheet .ape-sheet-sig {
  padding: 6px 10px; font: 12px/1.4 ui-monospace, Menlo, monospace; color: var(--ape-sheet-mute); white-space: nowrap; pointer-events: none;
  & b { color: var(--ape-sheet-ink); }
  & u { color: var(--ape-sheet-deep); font-weight: 700; text-decoration: none; background: var(--ape-sheet-tint); border-radius: 3px; padding: 0 2px; }
}

/* ── inspector ──────────────────────────────────────── */
.ape-sheet .ape-sheet-insp {
  grid-area: insp; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; padding: 14px 14px 12px;
  background: var(--ape-sheet-chrome); border-left: 1px solid var(--ape-sheet-line); scrollbar-width: thin;
}
.ape-sheet .ape-sheet-ihead {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px;
  & .ape-sheet-addr { font: 700 22px/1 ui-monospace, Menlo, monospace; letter-spacing: -.03em; }
  & .ape-sheet-kind { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--ape-sheet-mute); }
}
.ape-sheet .ape-sheet-icard { border-radius: 10px; padding: 10px 12px; background: var(--ape-sheet-bg); box-shadow: inset 0 0 0 1px var(--ape-sheet-line); }
.ape-sheet .ape-sheet-iformula {
  & code { display: block; font: 12.5px/1.5 ui-monospace, Menlo, monospace; overflow-wrap: anywhere; white-space: pre-wrap; }
  & .r0 { color: var(--ape-sheet-r0); } & .r1 { color: var(--ape-sheet-r1); } & .r2 { color: var(--ape-sheet-r2); } & .r3 { color: var(--ape-sheet-r3); } & .r4 { color: var(--ape-sheet-r4); }
  & .fn { color: var(--ape-sheet-deep); font-weight: 700; }
  & .num { color: oklch(0.5 0.13 255); }
  & .str { color: oklch(0.52 0.12 60); }
  & .op { color: var(--ape-sheet-mute); }
  & .ape-sheet-val { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--ape-sheet-line2); }
  & .ape-sheet-val b { font-size: 18px; font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
  & .ape-sheet-val small { color: var(--ape-sheet-mute); font: 11.5px/1 ui-monospace, Menlo, monospace; }
  & .ape-sheet-none { color: var(--ape-sheet-mute); font-size: 12.5px; }
}
.ape-sheet .ape-sheet-ilabel { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--ape-sheet-mute); margin-bottom: 6px; }
.ape-sheet .ape-sheet-ilinks {
  display: grid; grid-template-columns: 1fr; gap: 4px;
  & dt { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--ape-sheet-mute); margin-top: 4px; }
  & dd { display: flex; flex-wrap: wrap; gap: 4px; min-height: 24px; }
  & dd em { font-style: normal; color: var(--ape-sheet-faint); font-size: 12px; align-self: center; }
}
.ape-sheet .ape-sheet-chip {
  height: 22px; padding: 0 7px; border-radius: 6px; font: 600 11.5px/22px ui-monospace, Menlo, monospace;
  background: var(--ape-sheet-bg); box-shadow: inset 0 0 0 1px var(--ape-sheet-line2);
