.ape-board {
  /* theme: override these four to re-skin */
  --ape-board-bg: oklch(0.968 0.008 85);
  --ape-board-ink: oklch(0.26 0.02 260);
  --ape-board-accent: oklch(0.57 0.17 252);
  --ape-board-paper: oklch(0.995 0.003 85);

  --ape-board-yellow: oklch(0.93 0.105 96);
  --ape-board-pink: oklch(0.885 0.075 12);
  --ape-board-green: oklch(0.9 0.085 150);
  --ape-board-blue: oklch(0.895 0.058 232);
  --ape-board-orange: oklch(0.875 0.1 62);

  --ape-board-line: color-mix(in oklch, var(--ape-board-ink) 10%, transparent);
  --ape-board-line2: color-mix(in oklch, var(--ape-board-ink) 18%, transparent);
  --ape-board-mute: color-mix(in oklch, var(--ape-board-ink) 60%, var(--ape-board-paper));
  --ape-board-faint: color-mix(in oklch, var(--ape-board-ink) 35%, var(--ape-board-paper));
  --ape-board-hover: color-mix(in oklch, var(--ape-board-ink) 6%, transparent);
  --ape-board-tint: color-mix(in oklch, var(--ape-board-accent) 13%, var(--ape-board-paper));
  --ape-board-dot: color-mix(in oklch, var(--ape-board-ink) 20%, var(--ape-board-bg));
  --ape-board-shadow: 0 1px 1px color-mix(in oklch, var(--ape-board-ink) 8%, transparent), 0 10px 24px -14px color-mix(in oklch, var(--ape-board-ink) 40%, transparent);
  --ape-board-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-board-out: cubic-bezier(.32, .72, 0, 1);
  --ape-board-spring: linear(0, 0.13 4.5%, 0.46 11%, 0.82 18%, 1.02 25%, 1.08 31%, 1.06 37%, 1.01 47%, 0.996 58%, 1);

  position: relative; width: 100%; height: var(--ape-board-h, 680px);
  container-type: inline-size; container-name: ape-board;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-board-bg); color: var(--ape-board-ink); color-scheme: light;
  accent-color: var(--ape-board-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px var(--ape-board-line2);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--ape-board-accent); outline-offset: 2px; }
  & button { font: inherit; color: inherit; cursor: pointer; background: none; border: 0; padding: 0; }
  & h3, & p, & dl, & dd, & ul, & ol { margin: 0; }
  & ul, & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px 3px; border-radius: 4px; color: var(--ape-board-mute); background: var(--ape-board-paper); box-shadow: inset 0 0 0 1px var(--ape-board-line2); }
}

.ape-board .ape-board-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 268px;
  grid-template-rows: 54px minmax(0, 1fr);
  grid-template-areas: "top side" "vp side";
}

/* ── top bar ────────────────────────────────────────── */
.ape-board .ape-board-top {
  grid-area: top; position: relative; z-index: 5; display: flex; align-items: center; gap: 12px; padding: 0 12px 0 14px; min-width: 0;
  background: var(--ape-board-paper); border-bottom: 1px solid var(--ape-board-line);
}
.ape-board .ape-board-title {
  display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0;
  & small { display: block; font-size: 11.5px; color: var(--ape-board-mute); }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > div { min-width: 0; }
}
.ape-board .ape-board-logo {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; flex: none;
  background: var(--ape-board-ink); color: var(--ape-board-yellow);
  & svg { width: 18px; height: 18px; }
}
.ape-board .ape-board-peers {
  display: flex; padding-left: 6px;
  & span {
    display: grid; place-items: center; width: 28px; height: 28px; margin-left: -6px; border-radius: 50%;
    font: 700 10.5px/1 system-ui, sans-serif; color: var(--ape-board-paper); background: var(--c);
    box-shadow: 0 0 0 2px var(--ape-board-paper);
  }
  & span:first-child { box-shadow: 0 0 0 2px var(--ape-board-paper), 0 0 0 3.5px var(--c); }
}
.ape-board .ape-board-vote {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px 0 10px; border-radius: 8px; font-weight: 600; font-size: 13px;
  box-shadow: inset 0 0 0 1px var(--ape-board-line2); transition: background .2s, box-shadow .2s, color .2s;
  & .f { fill: currentColor; stroke: none; }
  & b { min-width: 20px; height: 20px; padding: 0 6px; border-radius: 10px; font: 700 11px/20px system-ui; font-variant-numeric: tabular-nums; background: var(--ape-board-hover); text-align: center; }
  &:hover { background: var(--ape-board-hover); }
  &[aria-pressed="true"] { background: var(--ape-board-ink); color: var(--ape-board-paper); box-shadow: none; }
  &[aria-pressed="true"] b { background: var(--ape-board-yellow); color: var(--ape-board-ink); }
  & b.is-bump { animation: ape-board-bump .4s var(--ape-board-spring); }
}
@keyframes ape-board-bump { 40% { scale: 1.3; } }
.ape-board .ape-board-ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--ape-board-mute); &:hover { background: var(--ape-board-hover); color: var(--ape-board-ink); } &[aria-pressed="true"] { background: var(--ape-board-tint); color: var(--ape-board-accent); } }
.ape-board .ape-board-panelbtn { display: none; }

/* ── viewport + world ───────────────────────────────── */
.ape-board .ape-board-vp {
  --z: 1; --iz: 1; --px: 0px; --py: 0px; --gs: 24px;
  grid-area: vp; position: relative; overflow: hidden; outline: none; touch-action: none; cursor: default;
  background-color: var(--ape-board-bg);
  background-image: radial-gradient(circle at center, var(--ape-board-dot) calc(1.1px * min(1, var(--z) * 1.4)), transparent calc(1.1px * min(1, var(--z) * 1.4) + .6px));
  background-size: var(--gs) var(--gs); background-position: var(--px) var(--py);
  &:focus-visible { outline: none; box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--ape-board-accent) 45%, transparent); }
}
.ape-board[data-tool="hand"] .ape-board-vp, .ape-board.is-space .ape-board-vp { cursor: grab; }
.ape-board.is-panning .ape-board-vp { cursor: grabbing; }
.ape-board:is([data-tool="sticky"], [data-tool="rect"], [data-tool="ellipse"], [data-tool="link"]) .ape-board-vp { cursor: crosshair; }
.ape-board[data-tool="text"] .ape-board-vp { cursor: text; }
.ape-board .ape-board-world { position: absolute; left: 0; top: 0; width: 0; height: 0; transform-origin: 0 0; will-change: transform; }
.ape-board .ape-board-links {
  position: absolute; left: 0; top: 0; width: 1px; height: 1px; overflow: visible; z-index: 2; pointer-events: none;
  & path.ln { stroke: color-mix(in oklch, var(--ape-board-ink) 62%, var(--ape-board-bg)); stroke-width: 2; fill: none; }
  & path.hit { stroke: transparent; stroke-width: 14; fill: none; pointer-events: stroke; cursor: pointer; }
  & g.is-sel path.ln { stroke: var(--ape-board-accent); stroke-width: 2.5; }
  & g:hover path.ln { stroke: var(--ape-board-accent); }
  & .ghost { stroke: var(--ape-board-accent); stroke-dasharray: 6 5; stroke-width: 2; fill: none; }
  & circle.end { fill: var(--ape-board-paper); stroke: color-mix(in oklch, var(--ape-board-ink) 62%, var(--ape-board-bg)); stroke-width: 2; }
}
.ape-board .ape-board-obj {
  position: absolute; left: 0; top: 0; z-index: 3;
  translate: var(--x) var(--y); width: var(--w); height: var(--h);
  outline: calc(1.5px * var(--iz)) solid transparent; outline-offset: calc(2px * var(--iz));
  transition: outline-color .12s, box-shadow .2s var(--ape-board-ease), scale .25s var(--ape-board-spring);
  &:hover { outline-color: color-mix(in oklch, var(--ape-board-accent) 55%, transparent); }
  &.is-sel { outline-color: var(--ape-board-accent); }
  &.is-target { outline: calc(3px * var(--iz)) solid var(--ape-board-accent); }
  &.is-new { animation: ape-board-pop .42s var(--ape-board-spring) both; }
}
.ape-board.is-moving .ape-board-obj.is-sel { box-shadow: 0 18px 30px -14px color-mix(in oklch, var(--ape-board-ink) 45%, transparent); }
@keyframes ape-board-pop { from { scale: .6; opacity: 0; } }
.ape-board .ape-board-sticky {
  --c: var(--ape-board-yellow);
  display: flex; flex-direction: column; padding: 14px 14px 10px; border-radius: 3px;
  background: linear-gradient(180deg, color-mix(in oklch, var(--c) 92%, white), var(--c));
  box-shadow: var(--ape-board-shadow);
  color: color-mix(in oklch, var(--ape-board-ink) 92%, var(--c));
  & .ape-board-txt { flex: 1; font-size: 15px; line-height: 1.32; font-weight: 520; letter-spacing: -.005em; text-wrap: pretty; overflow: hidden; outline: none; }
  &.is-s .ape-board-txt { font-size: 13px; }
  &.is-l .ape-board-txt { font-size: 18px; font-weight: 600; }
  & .ape-board-by { font-size: 11px; color: color-mix(in oklch, var(--ape-board-ink) 55%, var(--c)); font-weight: 550; }
}
.ape-board .ape-board-votes {
  position: absolute; top: -9px; right: -9px; display: flex; align-items: center; gap: 2px; height: 22px; padding: 0 7px 0 5px; border-radius: 11px;
  background: var(--ape-board-ink); color: var(--ape-board-paper); font: 700 11px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums;
  box-shadow: 0 0 0 2px var(--ape-board-paper);
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--ape-board-yellow); }
  & i.is-mine { background: var(--ape-board-orange); box-shadow: 0 0 0 1.5px var(--ape-board-paper); }
  &.is-bump { animation: ape-board-bump .45s var(--ape-board-spring); }
