.ape-review {
  /* theme: override these four to re-skin */
  --ape-review-bg: oklch(0.976 0.005 95);
  --ape-review-paper: oklch(0.997 0.002 95);
  --ape-review-ink: oklch(0.27 0.02 235);
  --ape-review-accent: oklch(0.52 0.1 192);

  --ape-review-add: oklch(0.6 0.15 150);
  --ape-review-del: oklch(0.58 0.17 25);
  --ape-review-addbg: color-mix(in oklch, oklch(0.9 0.08 150) 55%, var(--ape-review-paper));
  --ape-review-delbg: color-mix(in oklch, oklch(0.9 0.06 20) 55%, var(--ape-review-paper));
  --ape-review-addhi: color-mix(in oklch, var(--ape-review-add) 30%, var(--ape-review-paper));
  --ape-review-delhi: color-mix(in oklch, var(--ape-review-del) 26%, var(--ape-review-paper));
  --ape-review-line: color-mix(in oklch, var(--ape-review-ink) 10%, transparent);
  --ape-review-line2: color-mix(in oklch, var(--ape-review-ink) 17%, transparent);
  --ape-review-mute: color-mix(in oklch, var(--ape-review-ink) 60%, var(--ape-review-paper));
  --ape-review-faint: color-mix(in oklch, var(--ape-review-ink) 38%, var(--ape-review-paper));
  --ape-review-hover: color-mix(in oklch, var(--ape-review-ink) 5%, transparent);
  --ape-review-tint: color-mix(in oklch, var(--ape-review-accent) 11%, var(--ape-review-paper));
  --ape-review-deep: color-mix(in oklch, var(--ape-review-accent) 75%, var(--ape-review-ink));
  --ape-review-mono: 12.5px/1.6 ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --ape-review-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-review-out: cubic-bezier(.32, .72, 0, 1);
  --ape-review-spring: linear(0, 0.13 4.5%, 0.46 11%, 0.82 18%, 1.02 25%, 1.07 31%, 1.05 37%, 1.01 47%, 0.997 58%, 1);

  position: relative; width: 100%; height: var(--ape-review-h, 680px);
  container-type: inline-size; container-name: ape-review;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-review-bg); color: var(--ape-review-ink); color-scheme: light;
  accent-color: var(--ape-review-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px var(--ape-review-line2);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--ape-review-accent); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & h3, & p, & dl, & dd, & ul, & fieldset { margin: 0; }
  & ul { padding: 0; list-style: none; }
  & fieldset { border: 0; padding: 0; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10.5px/1 ui-monospace, Menlo, monospace; padding: 2px 5px 3px; border-radius: 4px; color: var(--ape-review-mute); background: var(--ape-review-paper); box-shadow: inset 0 0 0 1px var(--ape-review-line2), inset 0 -1px 0 var(--ape-review-line2); }
  & code { font: 600 .9em/1 ui-monospace, Menlo, monospace; padding: .15em .4em; border-radius: 4px; background: color-mix(in oklch, var(--ape-review-accent) 10%, var(--ape-review-paper)); color: var(--ape-review-deep); }
}
.ape-review .ape-review-vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.ape-review .ape-review-app {
  height: 100%; display: grid;
  grid-template-columns: 252px minmax(0, 1fr);
  grid-template-rows: auto 46px minmax(0, 1fr);
  grid-template-areas: "head head" "side bar" "side main";
}

/* ── header ─────────────────────────────────────────── */
.ape-review .ape-review-head { grid-area: head; padding: 14px 18px 12px; background: var(--ape-review-paper); border-bottom: 1px solid var(--ape-review-line); min-width: 0; }
.ape-review .ape-review-crumb {
  display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--ape-review-mute); font-weight: 550;
  & svg { width: 14px; height: 14px; }
  & span { color: var(--ape-review-faint); font-weight: 450; }
}
.ape-review .ape-review-title { margin-top: 4px; font-size: clamp(17px, 1.9cqi, 21px); font-weight: 720; letter-spacing: -.015em; line-height: 1.2; text-wrap: balance; }
.ape-review .ape-review-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-top: 9px; font-size: 12.5px; color: var(--ape-review-mute); }
.ape-review .ape-review-state {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 11px 0 9px; border-radius: 13px; font-weight: 650; font-size: 12.5px;
  color: var(--ape-review-paper); background: var(--ape-review-add);
  transition: background .3s, transform .4s var(--ape-review-spring);
  &[data-state="approve"] { background: color-mix(in oklch, var(--ape-review-add) 80%, var(--ape-review-ink)); }
  &[data-state="changes"] { background: var(--ape-review-del); }
  &[data-state="comment"] { background: var(--ape-review-accent); }
  &.is-bump { animation: ape-review-bump .5s var(--ape-review-spring); }
}
@keyframes ape-review-bump { 40% { transform: scale(1.08); } }
.ape-review .ape-review-who {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0;
  & b { color: var(--ape-review-ink); font-weight: 600; }
}
.ape-review .ape-review-av, .ape-review .ape-review-who i {
  display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; flex: none; font: 700 9.5px/1 system-ui, sans-serif; font-style: normal;
  background: var(--c); color: var(--ape-review-paper);
}
.ape-review .ape-review-stat { font-variant-numeric: tabular-nums; & .a { color: var(--ape-review-add); font-weight: 650; } & .d { color: var(--ape-review-del); font-weight: 650; } }
.ape-review .ape-review-checks { display: inline-flex; align-items: center; gap: 4px; color: var(--ape-review-add); font-weight: 550; & svg { width: 14px; height: 14px; stroke-width: 2; } }

/* ── toolbar ────────────────────────────────────────── */
.ape-review .ape-review-bar {
  grid-area: bar; display: flex; align-items: center; gap: 10px; padding: 0 12px 0 14px; min-width: 0;
  background: var(--ape-review-paper); border-bottom: 1px solid var(--ape-review-line);
}
.ape-review .ape-review-fill { flex: 1; }
.ape-review .ape-review-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 8px; font-size: 12.5px; font-weight: 600; white-space: nowrap;
  background: var(--ape-review-paper); box-shadow: inset 0 0 0 1px var(--ape-review-line2), 0 1px 0 var(--ape-review-line);
  transition: background .15s, box-shadow .15s, transform .15s var(--ape-review-ease);
  &:hover { background: var(--ape-review-bg); }
  &:active { transform: scale(.97); }
  &.is-primary, &.ape-review-submit { background: var(--ape-review-accent); color: var(--ape-review-paper); box-shadow: none; }
  &.is-primary:hover, &.ape-review-submit:hover { background: var(--ape-review-deep); }
  & b { min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; font: 700 10.5px/18px system-ui; text-align: center; background: color-mix(in oklch, var(--ape-review-paper) 25%, transparent); }
  & b[hidden] { display: none; }
  &[aria-pressed="true"] { background: var(--ape-review-tint); color: var(--ape-review-deep); }
}
.ape-review .ape-review-filesbtn { display: none; }
.ape-review .ape-review-seg {
  display: inline-grid; grid-auto-flow: column; padding: 2px; border-radius: 8px; background: var(--ape-review-bg); box-shadow: inset 0 0 0 1px var(--ape-review-line);
  & button { height: 26px; padding: 0 11px; border-radius: 6px; font-size: 12.5px; font-weight: 600; color: var(--ape-review-mute); transition: background .2s, color .2s, box-shadow .2s; }
  & button[aria-checked="true"] { background: var(--ape-review-paper); color: var(--ape-review-ink); box-shadow: 0 1px 2px var(--ape-review-line2), inset 0 0 0 1px var(--ape-review-line); }
  & button:disabled { opacity: .4; cursor: not-allowed; }
}
.ape-review .ape-review-ws { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--ape-review-mute); cursor: pointer; white-space: nowrap; & input { margin: 0; } }
.ape-review .ape-review-prog {
  display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--ape-review-mute); white-space: nowrap; font-variant-numeric: tabular-nums;
  & i { width: 84px; height: 6px; border-radius: 3px; background: var(--ape-review-line); overflow: hidden; }
  & b { display: block; height: 100%; border-radius: 3px; background: var(--ape-review-add); transform-origin: 0 50%; scale: var(--p, 0) 1; transition: scale .5s var(--ape-review-spring); }
}

/* ── file tree ──────────────────────────────────────── */
.ape-review .ape-review-side {
  grid-area: side; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 8px; padding: 12px 10px;
  background: var(--ape-review-paper); border-right: 1px solid var(--ape-review-line); scrollbar-width: thin;
}
.ape-review .ape-review-filter {
  display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 9px; border-radius: 8px; color: var(--ape-review-faint);
  box-shadow: inset 0 0 0 1px var(--ape-review-line2);
  & svg { width: 14px; height: 14px; }
  & input { flex: 1; min-width: 0; border: 0; outline: none; background: none; font-size: 12.5px; color: var(--ape-review-ink); }
  & input::-webkit-search-cancel-button { display: none; }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--ape-review-accent); }
}
.ape-review .ape-review-tree {
  display: grid; grid-template-columns: minmax(0, 1fr);
  & li { min-width: 0; }
  & .ape-review-dir { display: flex; align-items: center; gap: 6px; padding: 5px 6px 3px calc(6px + var(--d, 0) * 12px); font-size: 12px; color: var(--ape-review-faint); font-weight: 550; }
  & .ape-review-dir svg { width: 14px; height: 14px; }
  & [role="treeitem"] {
    display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; align-items: center; gap: 7px; padding: 5px 8px 5px calc(8px + var(--d, 0) * 12px);
    border-radius: 7px; cursor: pointer; font-size: 12.5px; outline-offset: -2px;
    transition: background .15s;
    &:hover { background: var(--ape-review-hover); }
    &[aria-current="true"] { background: var(--ape-review-tint); }
    & .n { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
