/**
 * Delay before the next attempt. With full jitter the delay is drawn
 * uniformly from [0, cap) so retries from many senders spread out.
 */
export function nextDelay(attempt: number, opts = DEFAULTS, rand = Math.random): number {
  const cap = Math.min(opts.baseMs * 2 ** attempt, opts.maxMs);
  if (opts.jitter === 'none') return cap;
  return Math.floor(rand() * cap);
