$('.ape-review-tree').addEventListener('click', e => { const li = e.target.closest('[data-go]'); if (li) scrollToFile(li.dataset.go); });
$('.ape-review-tree').addEventListener('keydown', e => {
  const items = $$('.ape-review-tree [role="treeitem"]'), i = items.indexOf(document.activeElement);
