css:
.ape-cut {
  /* theme: override these four to re-skin */
  --ape-cut-bg: oklch(0.165 0.004 70);
  --ape-cut-panel: oklch(0.205 0.005 70);
  --ape-cut-ink: oklch(0.93 0.006 90);
  --ape-cut-accent: oklch(0.89 0.19 124);

  --ape-cut-video: oklch(0.5 0.075 238);
  --ape-cut-title: oklch(0.64 0.14 355);
  --ape-cut-voice: oklch(0.6 0.105 176);
  --ape-cut-music: oklch(0.58 0.09 256);
  --ape-cut-line: color-mix(in oklch, var(--ape-cut-ink) 9%, transparent);
  --ape-cut-line2: color-mix(in oklch, var(--ape-cut-ink) 16%, transparent);
  --ape-cut-mute: color-mix(in oklch, var(--ape-cut-ink) 60%, var(--ape-cut-bg));
  --ape-cut-faint: color-mix(in oklch, var(--ape-cut-ink) 36%, var(--ape-cut-bg));
  --ape-cut-hover: color-mix(in oklch, var(--ape-cut-ink) 8%, transparent);
  --ape-cut-raised: color-mix(in oklch, var(--ape-cut-ink) 5%, var(--ape-cut-panel));
  --ape-cut-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-cut-out: cubic-bezier(.32, .72, 0, 1);
  --ape-cut-spring: linear(0, 0.14 5%, 0.5 12%, 0.86 20%, 1.03 27%, 1.06 33%, 1.03 40%, 1.004 52%, 1);

  position: relative; width: 100%; height: var(--ape-cut-h, 680px);
  container-type: inline-size; container-name: ape-cut;
  overflow: clip; isolation: isolate; box-sizing: border-box; outline: none;
  background: var(--ape-cut-bg); color: var(--ape-cut-ink); color-scheme: dark;
  accent-color: var(--ape-cut-accent);
  font: 12.5px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--ape-cut-ink) 12%, black);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 1.5px solid var(--ape-cut-accent); outline-offset: 1px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & p, & ul, & dl, & dd { margin: 0; }
  & ul { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border-radius: 4px; background: var(--ape-cut-hover); color: var(--ape-cut-mute); }
}

.ape-cut .ape-cut-app {
  height: 100%; display: grid;
  grid-template-columns: 208px minmax(0, 1fr) 236px;
  grid-template-rows: 46px minmax(0, 1fr) 258px;
  grid-template-areas: "top top top" "bin mon insp" "tl tl tl";
}

/* ── top bar ────────────────────────────────────────── */
.ape-cut .ape-cut-top {
  grid-area: top; display: flex; align-items: center; gap: 12px; padding: 0 10px 0 12px; min-width: 0;
  background: var(--ape-cut-panel); border-bottom: 1px solid var(--ape-cut-line);
}
.ape-cut .ape-cut-proj {
  display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0;
  & b { display: block; font-size: 13.5px; font-weight: 680; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11px; color: var(--ape-cut-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > div { min-width: 0; }
}
.ape-cut .ape-cut-logo { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 7px; flex: none; background: var(--ape-cut-accent); color: var(--ape-cut-bg); & svg { width: 17px; height: 17px; stroke-width: 1.7; } }
.ape-cut .ape-cut-seg { display: none; }
