    (c.kind === 'title' ? '<label class="ape-cut-ctl" style="grid-template-columns:1fr">Text<textarea data-prop="text" spellcheck="false">' + esc(c.text) + '</textarea></label>' : '') +
    '<div class="ape-cut-acts"><button type="button" data-act="split">Split  S</button><button type="button" data-act="del">Delete  ⌫</button><button type="button" class="is-wide" data-act="ripple">Ripple delete  ⇧⌫</button></div>';
}
let inspCommitted = false;
insp.addEventListener('input', e => {
