});

let toastT = 0;
function toast(t) { const el = $('.ape-cut-toast'); el.textContent = t; el.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => el.classList.remove('is-on'), 1800); }

function renderAll() { renderClips(); renderInsp(); drawRuler(); setTime(S.t); }
