ro.observe(mon); ro.observe(lanes);

/* ── boot ──────────────────────────────────────────── */
buildRows();
buildBin();
syncUndo();
renderClips(); renderInsp();
requestAnimationFrame(() => { if (!root.isConnected) return; fitZoom(); sizeMonitor(); setTime(S.t); });

