@property --ape-design-march {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

.ape-design {
  /* theme: override these four to re-skin */
  --ape-design-bg: oklch(0.236 0.006 255);
  --ape-design-canvas: oklch(0.182 0.005 255);
  --ape-design-ink: oklch(0.945 0.004 255);
  --ape-design-accent: oklch(0.68 0.19 12);

  --ape-design-on: oklch(0.99 0.004 12);
  --ape-design-line: color-mix(in oklch, var(--ape-design-ink) 9%, transparent);
  --ape-design-line2: color-mix(in oklch, var(--ape-design-ink) 16%, transparent);
  --ape-design-mute: color-mix(in oklch, var(--ape-design-ink) 62%, var(--ape-design-bg));
  --ape-design-faint: color-mix(in oklch, var(--ape-design-ink) 38%, var(--ape-design-bg));
  --ape-design-hover: color-mix(in oklch, var(--ape-design-ink) 7%, transparent);
  --ape-design-field: color-mix(in oklch, var(--ape-design-ink) 5.5%, var(--ape-design-bg));
  --ape-design-tint: color-mix(in oklch, var(--ape-design-accent) 22%, var(--ape-design-bg));
  --ape-design-tint2: color-mix(in oklch, var(--ape-design-accent) 12%, var(--ape-design-bg));
  --ape-design-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-design-out: cubic-bezier(.32, .72, 0, 1);
  --ape-design-spring: linear(0, 0.13 4.5%, 0.46 11%, 0.82 18%, 1.02 25%, 1.07 31%, 1.05 37%, 1.01 47%, 0.997 58%, 1);

  position: relative; width: 100%; height: var(--ape-design-h, 680px);
  container-type: inline-size; container-name: ape-design;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-design-bg); color: var(--ape-design-ink); color-scheme: dark;
  accent-color: var(--ape-design-accent);
  font: 12px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--ape-design-ink) 10%, black);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 1.5px solid var(--ape-design-accent); outline-offset: 1px; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & p, & ul, & dl, & dd, & h3, & h4, & pre { margin: 0; }
  & ul { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border-radius: 4px; background: var(--ape-design-hover); color: var(--ape-design-mute); }
}

.ape-design .ape-design-app {
  height: 100%; display: grid;
  grid-template-columns: 228px minmax(0, 1fr) 252px;
  grid-template-rows: 44px minmax(0, 1fr);
  grid-template-areas: "top top top" "layers stage insp";
}

/* ── top bar ────────────────────────────────────────── */
.ape-design .ape-design-top {
  grid-area: top; display: flex; align-items: center; gap: 12px; padding: 0 8px 0 10px; min-width: 0;
  border-bottom: 1px solid var(--ape-design-line);
}
.ape-design .ape-design-file {
  display: flex; align-items: center; gap: 9px; flex: 1; min-width: 0;
  & > div { min-width: 0; display: flex; align-items: baseline; gap: 8px; }
  & small { font-size: 11.5px; color: var(--ape-design-faint); white-space: nowrap; }
  & small::after { content: "/"; margin-left: 8px; color: var(--ape-design-line2); }
  & b { font-size: 12.5px; font-weight: 650; letter-spacing: -.005em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ape-design .ape-design-logo {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; flex: none;
  background: var(--ape-design-accent); color: var(--ape-design-on);
  & svg { width: 17px; height: 17px; stroke-width: 1.6; }
}
.ape-design .ape-design-seg { display: none; }
.ape-design .ape-design-right { display: flex; align-items: center; gap: 2px; }
.ape-design .ape-design-ib {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 7px; color: var(--ape-design-mute);
  transition: background .15s, color .15s, scale .2s var(--ape-design-spring);
  &:hover { background: var(--ape-design-hover); color: var(--ape-design-ink); }
  &:active { scale: .9; }
  &:disabled { opacity: .3; pointer-events: none; }
}
.ape-design .ape-design-zoomwrap { position: relative; margin-left: 4px; }
.ape-design .ape-design-zoom {
  display: flex; align-items: center; gap: 2px; height: 30px; padding: 0 6px 0 9px; border-radius: 7px;
  font-variant-numeric: tabular-nums; font-weight: 550; color: var(--ape-design-mute);
  & span { min-width: 34px; text-align: right; }
  & svg { width: 14px; height: 14px; transition: rotate .25s var(--ape-design-out); }
  &:hover, &[aria-expanded="true"] { background: var(--ape-design-hover); color: var(--ape-design-ink); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
}
.ape-design .ape-design-zmenu {
  position: absolute; right: 0; top: calc(100% + 6px); z-index: 40; width: 196px; padding: 5px; border-radius: 10px;
  background: color-mix(in oklch, var(--ape-design-ink) 4%, oklch(0.2 0.006 255)); box-shadow: 0 0 0 1px var(--ape-design-line2), 0 18px 40px -12px black;
  transform-origin: 100% 0; visibility: hidden; opacity: 0; scale: .96; translate: 0 -4px;
  transition: opacity .14s, scale .22s var(--ape-design-out), translate .22s var(--ape-design-out), visibility 0s .22s;
  &.is-open { visibility: visible; opacity: 1; scale: 1; translate: 0; transition: opacity .14s, scale .26s var(--ape-design-spring), translate .26s var(--ape-design-out), visibility 0s; }
  & button {
    display: flex; align-items: center; justify-content: space-between; width: 100%; height: 28px; padding: 0 8px; border-radius: 6px; text-align: left; outline-offset: -1.5px;
    &:hover, &:focus-visible { background: var(--ape-design-accent); color: var(--ape-design-on); & kbd { color: inherit; background: color-mix(in oklch, white 22%, transparent); } }
  }
  & hr { border: 0; height: 1px; margin: 4px 6px; background: var(--ape-design-line); }
}

/* ── layers ─────────────────────────────────────────── */
.ape-design .ape-design-layers {
  grid-area: layers; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--ape-design-line);
  background: var(--ape-design-bg); timeline-scope: --ape-design-ls;
}
.ape-design .ape-design-lhead {
  position: relative; z-index: 1; display: grid; gap: 8px; padding: 10px 10px 8px;
  & .ape-design-ltitle { display: flex; align-items: baseline; justify-content: space-between; padding: 0 2px; }
  & b { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; }
  & .ape-design-lcount { font-size: 11px; color: var(--ape-design-faint); font-variant-numeric: tabular-nums; }
}
@supports (animation-timeline: scroll()) {
  .ape-design .ape-design-lhead { animation: ape-design-lift linear both; animation-timeline: --ape-design-ls; animation-range: 0 24px; }
}
@keyframes ape-design-lift { to { box-shadow: 0 1px 0 var(--ape-design-line), 0 10px 16px -12px black; } }
.ape-design .ape-design-find {
  display: flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px; border-radius: 7px; background: var(--ape-design-field); color: var(--ape-design-faint);
  box-shadow: inset 0 0 0 1px transparent; transition: box-shadow .15s;
  &:focus-within { box-shadow: inset 0 0 0 1px var(--ape-design-accent); color: var(--ape-design-ink); }
  & svg { width: 14px; height: 14px; }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 12px; color: var(--ape-design-ink); }
  & input::placeholder { color: var(--ape-design-faint); }
}
.ape-design .ape-design-tree {
  flex: 1; min-height: 0; overflow-y: auto; padding: 2px 6px 12px; scroll-timeline: --ape-design-ls block;
  scrollbar-width: thin; scrollbar-color: var(--ape-design-line2) transparent;
}
.ape-design .ape-design-row {
  position: relative; display: flex; align-items: center; gap: 4px; height: 28px; padding: 0 4px 0 calc(4px + var(--d, 0) * 14px); border-radius: 6px; cursor: default; user-select: none; outline-offset: -1.5px;
  color: var(--ape-design-mute);
  & .ape-design-caret { display: grid; place-items: center; width: 14px; height: 20px; color: var(--ape-design-faint); & svg { width: 12px; height: 12px; transition: rotate .2s var(--ape-design-out); } }
  &[aria-expanded="false"] .ape-design-caret svg { rotate: -90deg; }
  & .ape-design-cpad { width: 14px; flex: none; }
  & .ape-design-ticon { width: 14px; height: 14px; color: var(--ape-design-faint); }
  & .ape-design-rname { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ape-design-rname mark { background: color-mix(in oklch, var(--ape-design-accent) 35%, transparent); color: var(--ape-design-ink); border-radius: 2px; }
  & .ape-design-rbtn { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 5px; color: var(--ape-design-faint); opacity: 0; transition: opacity .12s; & svg { width: 14px; height: 14px; } &:hover { color: var(--ape-design-ink); background: var(--ape-design-hover); } }
  & .ape-design-rbtn[aria-pressed="true"] { opacity: 1; }
  & input { flex: 1; min-width: 0; height: 22px; padding: 0 4px; border: 0; border-radius: 4px; outline: 1.5px solid var(--ape-design-accent); background: var(--ape-design-canvas); font-size: 12px; }
  &.is-frame { color: var(--ape-design-ink); font-weight: 600; & .ape-design-ticon { color: var(--ape-design-mute); } }
  &:hover { background: var(--ape-design-hover); & .ape-design-rbtn { opacity: 1; } }
  &.is-hov { background: var(--ape-design-hover); }
  &[aria-selected="true"] { background: var(--ape-design-tint); color: var(--ape-design-ink); & .ape-design-ticon { color: var(--ape-design-accent); } }
  &[aria-selected="true"] + &[aria-selected="true"] { border-top-left-radius: 0; border-top-right-radius: 0; }
  &.is-hidden .ape-design-rname, &.is-hidden .ape-design-ticon { opacity: .4; }
  &.is-drag { z-index: 3; background: var(--ape-design-field); box-shadow: 0 0 0 1px var(--ape-design-line2), 0 10px 22px -10px black; opacity: .95; }
}
.ape-design .ape-design-tree.is-dragging .ape-design-row { transition: translate .18s var(--ape-design-out); }
.ape-design .ape-design-tree .ape-design-row.is-drag { transition: none; }
.ape-design .ape-design-empty { padding: 18px 10px; color: var(--ape-design-faint); text-align: center; text-wrap: pretty; }

/* ── stage + canvas ─────────────────────────────────── */
.ape-design .ape-design-stage { grid-area: stage; position: relative; min-width: 0; min-height: 0; background: var(--ape-design-canvas); }
.ape-design .ape-design-vp {
  position: absolute; inset: 0; overflow: hidden; touch-action: none; outline: none; cursor: default; user-select: none; -webkit-user-select: none;
  &:focus-visible { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ape-design-accent) 30%, transparent); }
}
.ape-design[data-tool="frame"] .ape-design-vp, .ape-design[data-tool="rect"] .ape-design-vp, .ape-design[data-tool="ellipse"] .ape-design-vp { cursor: crosshair; }
.ape-design[data-tool="text"] .ape-design-vp { cursor: text; }
.ape-design[data-tool="hand"] .ape-design-vp, .ape-design.is-space .ape-design-vp { cursor: grab; }
.ape-design.is-panning .ape-design-vp { cursor: grabbing; }
.ape-design .ape-design-world { position: absolute; left: 0; top: 0; width: 0; height: 0; transform-origin: 0 0; will-change: transform; }

/* scene nodes: the user's document, painted from the scene graph */
.ape-design .ape-design-n {
  position: absolute; display: block;
  &.is-frame { overflow: clip; box-shadow: 0 0 0 .5px rgb(0 0 0 / .4), 0 18px 40px -24px black; }
  &.is-text { white-space: pre-wrap; overflow-wrap: break-word; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; cursor: default; outline: none; }
  &.is-text[contenteditable="true"], &.is-text[contenteditable="plaintext-only"] { cursor: text; user-select: text; caret-color: var(--ape-design-accent); }
  &.is-vector svg { width: 100%; height: 100%; display: block; overflow: visible; }
  &.is-map {
    background:
      radial-gradient(64px 46px at 74% 30%, oklch(0.88 0.06 140) 97%, transparent),
      radial-gradient(40px 30px at 22% 22%, oklch(0.88 0.06 140) 97%, transparent),
      linear-gradient(162deg, transparent 74%, oklch(0.86 0.045 225) 74.3%),
      linear-gradient(118deg, transparent 46.8%, oklch(0.99 0.004 90) 47% 50.4%, transparent 50.6%),
      linear-gradient(28deg, transparent 57.8%, oklch(0.99 0.004 90) 58% 60%, transparent 60.2%),
