@property --ape-pixel-ring {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.ape-pixel {
  /* theme: override these four to re-skin */
  --ape-pixel-bg: oklch(0.928 0.02 102);
  --ape-pixel-panel: oklch(0.962 0.014 102);
  --ape-pixel-ink: oklch(0.27 0.035 128);
  --ape-pixel-accent: oklch(0.63 0.2 36);

  --ape-pixel-on: oklch(0.985 0.01 90);
  --ape-pixel-mat: color-mix(in oklch, var(--ape-pixel-ink) 13%, var(--ape-pixel-bg));
  --ape-pixel-chk1: color-mix(in oklch, white 65%, var(--ape-pixel-panel));
  --ape-pixel-chk2: color-mix(in oklch, var(--ape-pixel-ink) 9%, var(--ape-pixel-panel));
  --ape-pixel-line: color-mix(in oklch, var(--ape-pixel-ink) 12%, transparent);
  --ape-pixel-line2: color-mix(in oklch, var(--ape-pixel-ink) 22%, transparent);
  --ape-pixel-mute: color-mix(in oklch, var(--ape-pixel-ink) 64%, var(--ape-pixel-panel));
  --ape-pixel-faint: color-mix(in oklch, var(--ape-pixel-ink) 42%, var(--ape-pixel-panel));
  --ape-pixel-hover: color-mix(in oklch, var(--ape-pixel-ink) 7%, transparent);
  --ape-pixel-tint: color-mix(in oklch, var(--ape-pixel-accent) 14%, var(--ape-pixel-panel));
  --ape-pixel-ease: cubic-bezier(.2, .8, .2, 1);
  --ape-pixel-out: cubic-bezier(.32, .72, 0, 1);
  --ape-pixel-spring: linear(0, 0.14 5%, 0.5 12%, 0.86 20%, 1.03 27%, 1.07 33%, 1.03 41%, 1.004 52%, 1);

  position: relative; width: 100%; height: var(--ape-pixel-h, 680px);
  container-type: inline-size; container-name: ape-pixel;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--ape-pixel-bg); color: var(--ape-pixel-ink); color-scheme: light;
  accent-color: var(--ape-pixel-accent);
  font: 12px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 12px; box-shadow: 0 0 0 1px var(--ape-pixel-line2);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--ape-pixel-accent); outline-offset: 1px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & p, & ol, & h3 { margin: 0; }
  & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 650 9px/1 ui-monospace, Menlo, monospace; }
}

.ape-pixel .ape-pixel-app {
  height: 100%; display: grid;
  grid-template-columns: 52px minmax(0, 1fr) 244px;
  grid-template-rows: 44px auto minmax(0, 1fr) 112px;
  grid-template-areas: "top top top" "tools stage prev" "tools stage pal" "tools frames pal";
}

/* ── top bar ────────────────────────────────────────── */
.ape-pixel .ape-pixel-top {
  grid-area: top; display: flex; align-items: center; gap: 12px; padding: 0 8px 0 10px; min-width: 0;
  border-bottom: 1px solid var(--ape-pixel-line);
}
.ape-pixel .ape-pixel-file {
  display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0;
  & > div { min-width: 0; }
  & b { display: block; font: 650 12.5px/1.25 ui-monospace, "SF Mono", Menlo, monospace; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font-size: 11px; color: var(--ape-pixel-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ape-pixel .ape-pixel-logo {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 6px; flex: none;
  background: var(--ape-pixel-ink); color: var(--ape-pixel-bg);
  & svg { width: 16px; height: 16px; fill: var(--ape-pixel-accent); stroke: none; }
}
.ape-pixel .ape-pixel-views {
  display: flex; padding: 2px; gap: 2px; border-radius: 8px; background: var(--ape-pixel-hover);
  & button { height: 26px; padding: 0 12px; border-radius: 6px; font-weight: 600; color: var(--ape-pixel-mute); transition: background .15s, color .15s, box-shadow .15s; }
  & button:hover { color: var(--ape-pixel-ink); }
  & button[aria-selected="true"] { background: var(--ape-pixel-panel); color: var(--ape-pixel-ink); box-shadow: 0 1px 0 var(--ape-pixel-line2), 0 1px 3px -1px var(--ape-pixel-line2); }
